export async function POST(req: NextRequest) {
  try {
    if (!isSameOriginMutation(req)) return NextResponse.json({ error: 'Yêu cầu không hợp lệ' }, { status: 403 });
    const currentUser = await requireAuth();
    assertRequestAccount(req.headers, currentUser.id);
    const body = await req.json();
    const customApiKey = requestApiKey(body);
    const question = normalizeQuestion(body.question);

    if (!question || !question.content) {
      return NextResponse.json({ error: 'Thiếu dữ liệu câu hỏi cần kiểm tra' }, { status: 400 });
    }

    let hasKeys = Boolean(customApiKey && customApiKey.trim());
    if (!hasKeys && currentUser) {
      const activeCount = await prisma.userApiKey.count({
        where: { userId: currentUser.id, isActive: true },
      });
      hasKeys = activeCount > 0;
    }

    if (!hasKeys) {
      return NextResponse.json(
        { error: 'Tài khoản chưa có Google Gemini API Key. Thầy/Cô vui lòng thêm khóa API trong mục Kho Khóa AI.' },
        { status: 401 }
      );
    }

    // Xây dựng đề bài giải MÙ (Blind Solve): Không cấp đáp án đã có để AI giải hoàn toàn độc lập
    let questionTextForSolver = `[NỘI DUNG ĐỀ BÀI]:\n${question.content}\n\n`;

    if (question.type === 'multiple_choice' && question.choices) {
      questionTextForSolver += `[CÁC LỰA CHỌN]:\n`;
      question.choices.forEach(c => {
        questionTextForSolver += `${c.key}. ${c.text}\n`;
      });
    } else if (question.type === 'true_false_group' && question.sub_questions) {
      questionTextForSolver += `[CÁC MỆNH ĐỀ CẦN XÉT ĐÚNG/SAI]:\n`;
      question.sub_questions.forEach(sq => {
        questionTextForSolver += `${sq.key}) ${sq.content}\n`;
      });
    }

    const prompt = `Bạn hỗ trợ giáo viên giải độc lập và rà soát câu hỏi. Không tự nhận đại diện cơ quan quản lý; kết quả cần giáo viên kiểm tra.
Nhiệm vụ của bạn là giải độc lập câu hỏi dưới đây từ các tiên đề cơ bản nhất để kiểm định chất lượng:
1. Giải bài toán từng bước một cách chặt chẽ, nêu rõ điều kiện và điều chưa chắc chắn.
2. Đưa ra kết luận đáp án độc lập (solvedAnswer).
3. Đánh giá xem đề bài có bị thiếu điều kiện xác định, thiếu dữ kiện, hoặc câu từ mơ hồ gây tranh cãi hay không.

${questionTextForSolver}

Yêu cầu xuất ra cấu trúc JSON hợp lệ theo Schema đã cung cấp.`;

    const responseText = await executeWithKeyRotation(
      customApiKey,
      async (apiKey, model) => {
        const ai = new GoogleGenAI({ apiKey });
        const response = await ai.models.generateContent({
          model,
          contents: prompt,
          config: {
            responseMimeType: 'application/json',
            responseSchema: geminiVerifySchema,
            temperature: 0.1, // Nhiệt độ cực thấp cho kết quả xác định, chuẩn xác
          },
        });
        return response.text || '{}';
      },
      {
        userId: currentUser.id,
        endpoint: 'question.verify',
      }
    );

    const parsedJson = parseProviderJson(responseText) as ReturnType<typeof JSON.parse>;
    const verifiedData = verifyZodSchema.parse(parsedJson);

    const { complete, isMatch, discrepancies } = compareAnswerReview(question, verifiedData);

    return NextResponse.json({
      success: true,
      isMatch,
      complete,
      reviewedQuestionId: question.id,
      reviewedVersion: question.version,
      solvedAnswer: verifiedData.solvedAnswer,
      confidence: verifiedData.confidence,
      solutionSteps: verifiedData.solutionSteps,
      subQuestionsAssessment: verifiedData.subQuestionsAssessment,
      discrepancies,
      recommendation: verifiedData.recommendation,
      originalAnswer: question.correct_answer,
    });
  } catch (error: unknown) {
    return apiErrorResponse(error, 'Không thể rà soát câu hỏi lúc này.');
  }
}

'use client';

import React, { useState, useEffect, use } from 'react';
import Link from 'next/link';
import {
  Users,
  BookOpen,
  Clock,
  CheckCircle2,
  PlayCircle,
  Calendar,
  AlertCircle,
  ChevronRight,
  GraduationCap,
} from 'lucide-react';

interface Student {
  id: string;
  displayName: string;
}

interface AssignmentItem {
  id: string;
  title: string;
  publicId: string;
  mode: string;
  durationMinutes?: number;
  opensAt?: string;
  closesAt?: string;
  attemptsCount: number;
  latestAttempt?: {
    id: string;
    status: 'IN_PROGRESS' | 'SUBMITTED' | 'TERMINATED';
    score: number | null;
    maxScore: number | null;
    submittedAt?: string;
  } | null;
}

interface GroupData {
  id: string;
  name: string;
  publicCode: string;
  students: Student[];
  assignments: AssignmentItem[];
}

function ClassPortalContent({
  params,
}: {
  params: Promise<{ groupCode: string }>;
}) {
  const { groupCode } = use(params);

  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [group, setGroup] = useState<GroupData | null>(null);
  const [selectedStudentId, setSelectedStudentId] = useState<string>('');

  const loadGroupData = (studentId?: string) => fetch(`/api/public/groups/${groupCode}${studentId ? `?studentId=${studentId}` : ''}`).then(async res => {
    const data = await res.json();
    if (!res.ok) { setError(data.error || 'Không thể tìm thấy lớp học'); return; }
    setGroup(data.group);
  }).catch(err => { console.error(err); setError('Lỗi kết nối máy chủ, vui lòng thử lại.'); }).finally(() => setLoading(false));
  const fetchGroupData = (studentId?: string) => { setLoading(true); setError(null); return loadGroupData(studentId); };

  useEffect(() => {
    void loadGroupData();
  }, [groupCode]);

  const handleSelectStudent = (studentId: string) => {
    setSelectedStudentId(studentId);
    if (studentId) {
      fetchGroupData(studentId);
    }
  };

  if (loading && !group) {
    return (
      <div className="min-h-screen bg-[#f8f9fa] dark:bg-[#181818] flex flex-col items-center justify-center text-[#202124] dark:text-[#e3e3e3] p-4">
        <div className="w-10 h-10 border-3 border-[#1a73e8] dark:border-[#8ab4f8] border-t-transparent rounded-full animate-spin mb-4" />
        <p className="text-[#5f6368] dark:text-[#9aa0a6] font-medium text-sm">Đang tải thông tin lớp học...</p>
      </div>
    );
  }

  if (error || !group) {
    return (
      <div className="min-h-screen bg-[#f8f9fa] dark:bg-[#181818] flex flex-col items-center justify-center text-[#202124] dark:text-[#e3e3e3] p-4">
        <div className="max-w-md w-full bg-white dark:bg-[#1e1e1e] border border-[#dadce0] dark:border-[#3c4043] rounded-3xl p-8 text-center shadow-xl">
          <AlertCircle className="w-12 h-12 text-[#c5221f] dark:text-[#f28b82] mx-auto mb-4" />
          <h2 className="text-xl font-bold text-[#202124] dark:text-[#e3e3e3] mb-2">Không tìm thấy lớp học</h2>
          <p className="text-[#5f6368] dark:text-[#9aa0a6] text-sm mb-6">{error}</p>
          <Link
            href="/"
            className="inline-flex items-center justify-center px-5 py-2.5 bg-[#1a73e8] dark:bg-[#8ab4f8] hover:bg-[#1557b0] dark:hover:bg-[#aecbfa] text-white dark:text-[#202124] text-sm font-semibold rounded-full transition-all shadow-xs"
          >
            Về trang chủ
          </Link>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#f8f9fa] dark:bg-[#181818] text-[#202124] dark:text-[#e3e3e3] py-10 px-4">
      <div className="max-w-4xl mx-auto space-y-6">
        {/* Banner Lớp học */}
        <div className="bg-white dark:bg-[#1e1e1e] border border-[#dadce0] dark:border-[#3c4043] rounded-3xl p-6 md:p-8 shadow-xs relative overflow-hidden">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 relative z-10">
            <div>
              <div className="flex items-center gap-2 text-[#1a73e8] dark:text-[#8ab4f8] text-xs font-bold uppercase tracking-wider mb-2">
                <GraduationCap className="w-4 h-4" /> Lớp học trực tuyến
              </div>
              <h1 className="text-2xl md:text-3xl font-bold text-[#202124] dark:text-[#e3e3e3]">{group.name}</h1>
              <p className="text-[#5f6368] dark:text-[#9aa0a6] text-xs md:text-sm mt-1">
                Mã lớp: <span className="font-mono font-bold text-[#1a73e8] dark:text-[#8ab4f8]">{group.publicCode}</span> •{' '}
                {group.students.length} học sinh
              </p>
            </div>

            {/* Chọn tên học sinh */}
            <div className="bg-[#f8f9fa] dark:bg-[#242424] border border-[#dadce0] dark:border-[#3c4043] p-4 rounded-2xl min-w-[280px]">
              <label className="block text-xs font-semibold text-[#5f6368] dark:text-[#9aa0a6] uppercase tracking-wider mb-2">
