export default function LoginPage() {
  const router = useRouter();
  const { theme, toggleTheme } = useTheme();

  // Login form state
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [errorMessage, setErrorMessage] = useState('');

  // Forced password change state
  const [showChangeModal, setShowChangeModal] = useState(false);
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [isChangingPassword, setIsChangingPassword] = useState(false);
  const [changeError, setChangeError] = useState('');
  const [loggedInUser, setLoggedInUser] = useState<{ id: string; role: string } | null>(null);
  useEffect(() => {
    let active = true;
    void fetch('/api/auth/me', { cache: 'no-store' }).then(response => response.json()).then(data => {
      if (active && data.user?.mustChangePassword) { setLoggedInUser(data.user); setShowChangeModal(true); }
    }).catch(() => { /* The login form remains usable when session lookup fails. */ });
    return () => { active = false; };
  }, []);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setErrorMessage('');
    setIsLoading(true);

    try {
      const res = await fetch('/api/auth/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password }),
      });

      const data = await res.json();

      if (!res.ok) {
        setErrorMessage(data.error || 'Đăng nhập không thành công');
        setIsLoading(false);
        return;
      }

      // Nếu tài khoản mới phải đổi mật khẩu lần đầu
      if (data.user.mustChangePassword) {
        setLoggedInUser(data.user);
        setShowChangeModal(true);
        setIsLoading(false);
        return;
      }

      // Điều hướng theo vai trò
      const dest = data.user.role === 'SUPER_ADMIN' ? '/admin/users' : '/';
      window.location.href = dest;
    } catch {
      setErrorMessage('Không thể kết nối đến máy chủ. Vui lòng kiểm tra lại mạng.');
      setIsLoading(false);
    }
  };

  const handleForcedPasswordChange = async (e: React.FormEvent) => {
    e.preventDefault();
    setChangeError('');

    if (newPassword.length < 8) {
      setChangeError('Mật khẩu mới phải có ít nhất 8 ký tự.');
      return;
    }

    if (newPassword !== confirmPassword) {
      setChangeError('Mật khẩu xác nhận không khớp.');
      return;
    }

    setIsChangingPassword(true);

    try {
      const res = await fetch('/api/auth/change-password', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ newPassword }),
      });

      const data = await res.json();

      if (!res.ok) {
        setChangeError(data.error || 'Đổi mật khẩu thất bại.');
        setIsChangingPassword(false);
        return;
      }

      // Đổi mật khẩu thành công -> Chuyển trang tức thì
      const dest = loggedInUser?.role === 'SUPER_ADMIN' ? '/admin/users' : '/';
      window.location.href = dest;
    } catch {
      setChangeError('Lỗi kết nối máy chủ khi cập nhật mật khẩu.');
      setIsChangingPassword(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#f8f9fa] dark:bg-[#181818] flex flex-col justify-center items-center px-4 py-12 relative overflow-hidden text-[#202124] dark:text-[#e3e3e3] transition-colors duration-200">
      {/* Background Glow */}
      <div className="absolute top-1/4 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[550px] h-[550px] bg-[#1a73e8]/10 dark:bg-[#8ab4f8]/10 rounded-full blur-[130px] pointer-events-none" />

      {/* Theme Toggle Button at top-right */}
      <div className="absolute top-5 right-5 z-20">
        <button
          type="button"
          onClick={toggleTheme}
          title={theme === 'dark' ? 'Chuyển sang giao diện Sáng' : 'Chuyển sang giao diện Tối'}
          className="p-2.5 rounded-full border border-[#dadce0] dark:border-[#3c4043] bg-white dark:bg-[#242424] text-[#5f6368] hover:text-[#202124] dark:text-[#9aa0a6] dark:hover:text-[#e3e3e3] hover:bg-[#f1f3f4] dark:hover:bg-[#282828] shadow-xs transition-colors cursor-pointer"
        >
          {theme === 'dark' ? <Sun className="w-4 h-4 text-amber-400" /> : <Moon className="w-4 h-4 text-[#5f6368]" />}
        </button>
      </div>

      {/* Main Card */}
      <div className="w-full max-w-md relative z-10">
        {/* Brand Header */}
        <div className="text-center mb-8">
          <div className="inline-flex items-center justify-center w-14 h-14 rounded-2xl bg-[#1a73e8] dark:bg-[#8ab4f8] shadow-lg mb-4">
            <Sparkles className="w-7 h-7 text-white dark:text-[#181818]" />
          </div>
          <h1 className="text-2xl font-bold tracking-tight text-[#202124] dark:text-[#e3e3e3] flex items-center justify-center gap-2">
            ExamCraft <span className="text-xs px-2.5 py-0.5 rounded-full bg-[#e8f0fe] dark:bg-[#1e2a38] text-[#1a73e8] dark:text-[#8ab4f8] border border-[#1a73e8]/20 dark:border-[#8ab4f8]/30 font-semibold">v3.1</span>
          </h1>
          <p className="text-sm text-[#5f6368] dark:text-[#9aa0a6] mt-1.5">
            Trợ lý Soạn Đề AI & Quản Lý Thi Chuẩn GDPT 2018
          </p>
        </div>

        {/* Card Box */}
        <div className="bg-white dark:bg-[#1e1e1e] border border-[#dadce0] dark:border-[#3c4043] rounded-3xl shadow-xl p-7 sm:p-8">
          <div className="mb-6">
            <h2 className="text-lg font-bold text-[#202124] dark:text-[#e3e3e3]">Đăng nhập tài khoản</h2>
            <p className="text-xs text-[#5f6368] dark:text-[#9aa0a6] mt-1">
