              {/* Thông tin học sinh */}
              <div className="text-[12pt] italic py-1 flex justify-between">
                <span>Họ và tên thí sinh: ........................................................................</span>
                <span>Lớp: ......... SBD: ..........</span>
              </div>

              {/* Ngữ liệu đọc hiểu chung nếu có */}
              {passages && passages.length > 0 && (
                <div className="space-y-3 pb-2">
                  {passages.map((p) => (
                    <div key={p.id} className="p-3 bg-[#f8f9fa] border border-[#dadce0] rounded-lg text-[11pt]">
                      <div className="font-bold text-black mb-1">{p.title || 'NGỮ LIỆU ĐỌC HIỂU:'}</div>
                      <div className="italic text-[#202124] leading-relaxed whitespace-pre-line">{p.content}</div>
                      {p.figures?.map(renderPreviewFigure)}
                      {p.source && <div className="text-right text-[10pt] text-[#5f6368] mt-1">({p.source})</div>}
                    </div>
                  ))}
                </div>
              )}

              {/* Nội dung đề thi */}
              {questions.length === 0 ? (
                <div className="py-24 text-center text-[#5f6368] italic text-[11pt]">
                  (Đề thi hiện chưa có câu hỏi nào. Hãy bấm &quot;Thêm câu hỏi&quot; hoặc &quot;Sinh đề AI Mới&quot; ở bảng bên trái để bắt đầu soạn đề.)
                </div>
              ) : (
                <>
                  <div className="space-y-4">
                    {questions.map((q, index) => <div key={q.id} className="question-item text-[12pt]">
                      {q.sectionId && questions[index - 1]?.sectionId !== q.sectionId && <h3 className="font-bold my-3">{exam.sections?.find(s => s.id === q.sectionId)?.title ?? exam.sections?.find(s => s.id === q.sectionId)?.label ?? exam.sections?.find(s => s.id === q.sectionId)?.name}</h3>}
                      <p className="leading-relaxed"><b>Câu {index + 1}:</b> {numericScore && q.points !== undefined && <span className="italic">({formatPointsString(q.points)}) </span>}<MathRenderer content={q.content} inline /></p>
                      {q.passageId && <p className="italic text-[10pt]">Theo ngữ liệu: {passages?.find(p => p.id === q.passageId)?.title ?? q.passageId}</p>}
                      {q.choices && q.type === 'multiple_choice' && <div className="grid grid-cols-2 gap-3 pl-4 py-2">{q.choices.map(choice => <p key={choice.key}><b>{choice.key}.</b> <MathRenderer content={choice.text} inline /></p>)}</div>}
                      {q.sub_questions && q.type === 'true_false_group' && <div className="pl-4 space-y-1">{q.sub_questions.map(sub => <p key={sub.key}><b>{sub.key})</b> <MathRenderer content={sub.content} inline /> <span className="whitespace-nowrap">□ Đúng □ Sai</span></p>)}</div>}
                      {renderStructuredPrompt(q)}
                      {q.figures?.map(renderPreviewFigure)}
                      {['short_answer', 'fill_blank'].includes(q.type) && <p className="mt-2">Trả lời: ................................................................................</p>}
                    </div>)}
                  </div>

                  {headerLines.filter(line => line.area === 'footer').map(line => <div key={line.id} data-header-line={line.id} className={`text-[11pt] whitespace-pre-wrap break-words ${line.bold ? 'font-bold' : ''} ${line.italic ? 'italic' : ''}`} style={{ textAlign: line.align, minHeight: '1.2em' }}>{line.text}</div>)}
                  {/* Chân trang đề thi */}
                  <div className="text-center text-[12pt] font-bold pt-8 border-t border-black mt-8">
                    ---------- HẾT ----------
                  </div>
                </>
              )}
            </div>
          )}

          {viewMode === 'exam' && questions.length === 0 && headerLines.filter(line => line.area === 'footer').map(line => <div key={line.id} data-header-line={line.id} className={`text-[11pt] whitespace-pre-wrap break-words ${line.bold ? 'font-bold' : ''} ${line.italic ? 'italic' : ''}`} style={{ textAlign: line.align, minHeight: '1.2em' }}>{line.text}</div>)}
          {/* VIEW: SONG SONG — đề bên trái, đáp án và lời giải bên phải; chỉ để xem/in, không đổi dữ liệu */}
          {viewMode === 'parallel' && (
            <div className="space-y-4 text-[12pt]">
              <h2 className="font-bold text-center text-[14pt]">ĐỀ VÀ ĐÁP ÁN SONG SONG</h2>
              <p className="text-center">{metadata.title}{metadata.examCode ? ' — Mã đề: ' + metadata.examCode : ''}</p>
              <p className="text-center italic text-[10pt]">Bản này chứa đáp án: chỉ dùng cho giáo viên, không phát cho học sinh.</p>
              {questions.length === 0 ? (
                <div className="py-16 text-center text-[#5f6368] italic text-[11pt]">(Chưa có câu hỏi nào.)</div>
              ) : metadata.assessmentMode === 'survey' ? (
                <div className="py-8 text-center italic text-[11pt]">Phiếu khảo sát không có đáp án đúng; hãy xem ở chế độ Đề thi in ấn.</div>
              ) : (
                <div className="border border-black">
                  <div className="grid grid-cols-2 border-b border-black font-bold text-center text-[11pt]"><div className="p-2 border-r border-black">ĐỀ</div><div className="p-2">ĐÁP ÁN VÀ HƯỚNG DẪN</div></div>
                  {parallelRows(questions, passages).map(row => {
                    if (row.kind === 'passage') return <div key={'passage-' + row.passage.id} data-parallel-passage={row.passage.id} className="parallel-passage border-b border-black p-2 text-[11pt] break-inside-avoid">
                      <div className="font-bold mb-1">{row.passage.title || 'NGỮ LIỆU ĐỌC HIỂU:'}</div>
                      <div className="italic leading-relaxed whitespace-pre-line">{row.passage.content}</div>
                      {row.passage.figures?.map(renderPreviewFigure)}
                      {row.passage.source && <div className="text-right text-[10pt] mt-1">({row.passage.source})</div>}
                    </div>;
                    const { question: q, index } = row;
                    const answer = parallelAnswer(q);
                    return <div key={q.id} className="question-item grid grid-cols-2 border-b border-black last:border-b-0 break-inside-avoid">
                      <div className="p-2 border-r border-black text-[11pt]">
                        <p className="leading-relaxed"><b>Câu {index + 1}:</b> {numericScore && q.points !== undefined && <span className="italic">({formatPointsString(q.points)}) </span>}<MathRenderer content={q.content} /></p>
                        {q.choices && q.type === 'multiple_choice' && <div className="pl-3 py-1">{q.choices.map(choice => <p key={choice.key}><b>{choice.key}.</b> <MathRenderer content={choice.text} inline /></p>)}</div>}
                        {q.sub_questions && q.type === 'true_false_group' && <div className="pl-3 space-y-1">{q.sub_questions.map(sub => <p key={sub.key}><b>{sub.key})</b> <MathRenderer content={sub.content} inline /></p>)}</div>}
                        {renderStructuredPrompt(q)}
                        {q.figures?.map(renderPreviewFigure)}
                      </div>
                      <div className="p-2 text-[11pt]">
                        <p className="font-bold text-emerald-800">{answer.headline}</p>
                        {answer.details.map((line, i) => <p key={i} className="text-[10pt]">{line}</p>)}
                        {answer.solution && <div className="mt-1 text-[10.5pt] leading-relaxed"><MathRenderer content={answer.solution} /></div>}
                      </div>
                    </div>;
                  })}
                </div>
              )}
            </div>
          )}

          {viewMode === 'answers' && <div className="space-y-5 text-[12pt]">
            <h2 className="font-bold text-center text-[14pt]">{metadata.assessmentMode === 'survey' ? 'PHIẾU KHẢO SÁT — KHÔNG CHẤM ĐÚNG SAI' : 'ĐÁP ÁN VÀ TIÊU CHÍ ĐÁNH GIÁ'}</h2>
            <p className="text-center">{metadata.title}{metadata.examCode ? ' — Mã đề: ' + metadata.examCode : ''}</p>
            <p>{numericScore ? 'Tổng điểm đã cấu hình: ' + totalPoints : 'Không tính điểm'}</p>
            {metadata.assessmentMode !== 'survey' && questions.map((q, index) => <section key={q.id} className="question-item border-b pb-3">
              <p><b>Câu {index + 1}:</b> {q.type === 'true_false_group' ? q.sub_questions?.map(sub => sub.key + ') ' + (sub.isCorrect === undefined ? 'Chưa có đáp án' : sub.isCorrect ? 'Đúng' : 'Sai')).join('; ') : q.type === 'matching' ? q.matchingPairs?.map(pair => pair.left + ' → ' + pair.right).join('; ') || q.correct_answer || 'Chưa thiết lập cặp đúng' : q.type === 'ordering' ? q.correctOrder?.join(' → ') || q.correct_answer || 'Chưa thiết lập thứ tự đúng' : q.correct_answer || (q.type === 'essay' ? 'Giáo viên đánh giá theo tiêu chí' : 'Chưa đặt đáp án')}</p>
              {q.accepted_answers?.filter(Boolean).length ? <p>Chấp nhận: {q.accepted_answers.filter(Boolean).join('; ')}</p> : null}
              {q.rubric?.map((row, i) => <p key={i}>• {row.criterion}{numericScore ? ': ' + row.maxPoints + ' điểm' : ''}</p>)}
            </section>)}
          </div>}

          {/* VIEW: HƯỚNG DẪN GIẢI CHI TIẾT */}
          {viewMode === 'solutions' && (
            <div className="space-y-6 text-[12pt]">
              <div className="page-break text-center border-b border-black pb-3">
                <h2 className="text-[14pt] font-bold uppercase">HƯỚNG DẪN GIẢI CHI TIẾT TỪNG BƯỚC</h2>
                <p className="italic text-[11pt]">Đề kiểm tra: {metadata.title} - Mã đề: {metadata.examCode || ''}</p>
              </div>

              {questions.length === 0 ? (
                <div className="py-16 text-center text-[#5f6368] italic text-[11pt]">
                  (Chưa có câu hỏi nào để hiển thị lời giải chi tiết.)
                </div>
              ) : (
                <div className="space-y-6">
                  {questions.map((q, idx) => (
                    <div key={q.id} className="question-item pb-4 border-b border-[#dadce0] last:border-b-0">
                      <div className="font-bold text-[12pt] text-[#202124]">
                        Câu {idx + 1}: {' '}
                        {q.type === 'multiple_choice' && (
                          <span className="text-emerald-700">Đáp án đúng là {q.correct_answer ?? 'Chưa có đáp án'}</span>
                        )}
                        {q.type === 'true_false_group' && (
                          <span className="text-emerald-700">
                            Đáp án: {q.sub_questions?.map(sq => `${sq.key}) ${typeof sq.isCorrect === 'boolean' ? (sq.isCorrect ? 'Đúng' : 'Sai') : 'Chưa có đáp án'}`).join('   ') || q.correct_answer}
                          </span>
                        )}
                        {q.type === 'short_answer' && (
                          <span className="text-emerald-700">Đáp số: {q.correct_answer}</span>
                        )}
                      </div>
                      {q.type === 'true_false_group' && q.sub_questions && (
                        <div className="pl-4 space-y-1 my-2 text-[11pt]">
                          {q.sub_questions.map(sq => (
                            <div key={sq.key} className="text-[#202124]">
                              <strong>Ý {sq.key}) ({typeof sq.isCorrect === 'boolean' ? (sq.isCorrect ? 'Đúng' : 'Sai') : 'Chưa có đáp án'}):</strong>{' '}
                              <MathRenderer content={sq.explanation || sq.content} inline />
                            </div>
                          ))}
                        </div>
                      )}
                      <div className="text-[12pt] text-[#202124] leading-relaxed pl-4">
                        <MathRenderer content={q.step_by_step_solution || 'Chưa có lời giải'} />
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}

          {/* VIEW: MA TRẬN & BẢN ĐẶC TẢ THEO CV 7991 */}
          {viewMode === 'matrix' && (
            <div className="space-y-6 text-[10pt]">
              {planOutput && <section className="space-y-2">
                <h2 className="text-center font-bold text-[12pt]">{planOutput.title}</h2>
                <p>{planOutput.disclaimer}</p><p className="font-bold">{planOutput.status}</p>
                {planOutput.summaries.map(summary => <p key={summary}>{summary}</p>)}
                {planOutput.headers.length > 0 && <table className="w-full table-fixed border-collapse border border-black text-[9pt]"><thead><tr>{planOutput.headers.map(header => <th key={header} className="border border-black p-1 break-words">{header}</th>)}</tr></thead><tbody>{planOutput.rows.map((row, index) => <tr key={index}>{row.map((cell, column) => <td key={column} className="border border-black p-1 align-top break-words">{cell}</td>)}</tr>)}</tbody></table>}
                {planOutput.warnings.length > 0 && <div className="border border-black p-2"><strong>Cần rà soát</strong>{planOutput.warnings.map((warning, index) => <p key={index}>{warning}</p>)}</div>}
              </section>}
              <h2 className="text-center font-bold text-[13pt]">MA TRẬN TỪ NỘI DUNG ĐANG SOẠN</h2>
              <p>Môn: {subjectConfig.name} · Lớp {metadata.grade}</p>
              <div className="border rounded-xl p-3 text-[10pt] space-y-1">{matrixData.warnings.map(warning => <p key={warning}>{warning}</p>)}</div>
              <table className="w-full border-collapse border border-black text-center">
                <thead><tr>{['Chủ đề', ...matrixData.cognitiveLabels.map(level => level.label), 'Chưa gắn mức', 'Tổng câu', numericScore ? 'Điểm' : 'Đánh giá'].map(label => <th key={label} className="border border-black p-2">{label}</th>)}</tr></thead>
                <tbody>{matrixData.rows.map(row => <tr key={row.index}>
                  <td className="border border-black p-2 text-left">{row.topicName}</td>
                  {matrixData.cognitiveLabels.map(level => <td key={level.id} className="border border-black p-2">{Object.values(row.cognitiveCounts[level.id]).reduce((sum, count) => sum + count, 0)}</td>)}
                  <td className="border border-black p-2">{row.unmappedCount}</td><td className="border border-black p-2">{row.totalQuestions}</td><td className="border border-black p-2">{numericScore ? row.totalPoints : 'Nhận xét'}</td>
                </tr>)}</tbody>
                <tfoot><tr><th className="border border-black p-2">Tổng</th>{matrixData.cognitiveTotals.map(level => <td key={level.id} className="border border-black p-2">{level.count}</td>)}<td className="border border-black p-2">{matrixData.unmappedCognitiveCount}</td><td className="border border-black p-2">{matrixData.totalQuestions}</td><td className="border border-black p-2">{numericScore ? matrixData.totalExamPoints : 'Không tính điểm'}</td></tr></tfoot>
              </table>
              <h3 className="font-bold text-center text-[12pt]">BẢN ĐẶC TẢ ĐANG SOẠN</h3>
              <table className="w-full border-collapse border border-black">
                <thead><tr><th className="border border-black p-2">Chủ đề</th><th className="border border-black p-2">Yêu cầu cần đạt</th>{matrixData.cognitiveLabels.map(level => <th key={level.id} className="border border-black p-2">{level.label}</th>)}<th className="border border-black p-2">Chưa gắn mức</th></tr></thead>
                <tbody>{specData.map(spec => <tr key={spec.index}><td className="border border-black p-2">{spec.topicName}</td><td className="border border-black p-2">{spec.requirement}</td>{matrixData.cognitiveLabels.map(level => <td key={level.id} className="border border-black p-2">{spec.cognitiveQuestions[level.id]?.map(number => 'C' + number).join(', ') || '—'}</td>)}<td className="border border-black p-2">{spec.unmappedQuestions.map(number => 'C' + number).join(', ') || '—'}</td></tr>)}</tbody>
              </table>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

'use client';

import React, { useState, useEffect, useLayoutEffect, useRef } from 'react';
import { Exam, Question } from '@/types/exam';
import { AiProposalPreview } from './AiProposalPreview';
import { 
  Sparkles, 
  Send, 
  RefreshCw, 
  HelpCircle, 
  CheckCircle2, 
  AlertCircle, 
  ChevronRight, 
  Wand2, 
  Flame, 
  ArrowDownCircle, 
  Binary,
  Compass
} from 'lucide-react';

interface ExamCopilotBarProps {
  exam: Exam;
  apiKey?: string;
  selectedQuestionIds: string[];
  externalCommand?: string;
  onUpdateQuestion: (updatedQuestion: Question) => void;
  onAddQuestion: (newQuestion: Question) => void;
  onDeleteQuestion: (id: string) => void;
  onBatchUpdateQuestions: (updatedQuestions: Question[]) => void;
}

export const ExamCopilotBar: React.FC<ExamCopilotBarProps> = ({
  exam,
  apiKey,
  selectedQuestionIds,
  externalCommand,
  onUpdateQuestion,
  onAddQuestion,
  onDeleteQuestion,
  onBatchUpdateQuestions,
}) => {
  const [commandDraft, setCommandDraft] = useState({ external: externalCommand, value: '' });
  const command = externalCommand && commandDraft.external !== externalCommand ? externalCommand : commandDraft.value;
  const setCommand = (value: string) => setCommandDraft({ external: externalCommand, value });
  const liveExam = useRef(exam);
  useLayoutEffect(() => { liveExam.current = exam; }, [exam]);
  const [proposal, setProposal] = useState<{ result: { action: string; modifiedQuestion?: Question; targetQuestionId?: string; explanation?: string }; base: string } | null>(null);
  const acceptProposal = () => {
    if (!proposal) return;
    if (JSON.stringify(liveExam.current.questions) !== proposal.base) { setErrorMessage('Đề đã thay đổi. Hãy gửi lại yêu cầu để giữ các sửa đổi mới.'); setProposal(null); return; }
    const result = proposal.result;
    if (result.action === 'modify_single_question' && result.modifiedQuestion) onUpdateQuestion(result.modifiedQuestion);
    else if (result.action === 'add_question' && result.modifiedQuestion) onAddQuestion(result.modifiedQuestion);
    else if (result.action === 'delete_question' && result.targetQuestionId) onDeleteQuestion(result.targetQuestionId);
    else { setErrorMessage('Đề xuất chưa đủ thông tin để áp dụng.'); return; }
    setProposal(null); setSuccessMessage('Đã áp dụng đề xuất. Thầy/cô kiểm tra lại trước khi chốt.');
  };
  const [isLoading, setIsLoading] = useState(false);
  const [clarification, setClarification] = useState<{
    message: string;
    quickOptions: string[];
  } | null>(null);
  const [customClarificationText, setCustomClarificationText] = useState('');
  const [successMessage, setSuccessMessage] = useState<string | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  useEffect(() => {
    if (externalCommand) {
      const inputEl = document.getElementById('exam-copilot-input');
      if (inputEl) {
        inputEl.focus();
        inputEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }
    }
  }, [externalCommand]);

  const handleSendCommand = async (cmdText?: string) => {
    const textToSend = cmdText || command;
    if (!textToSend.trim()) return;

    const base = JSON.stringify(exam.questions);
    setIsLoading(true);
    setProposal(null);
    setClarification(null);
    setSuccessMessage(null);
    setErrorMessage(null);

    try {
      const res = await fetch('/api/exam-copilot', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          exam,
          command: textToSend,
          targetQuestionId: selectedQuestionIds.length === 1 ? selectedQuestionIds[0] : undefined,
          customApiKey: apiKey,
        }),
      });

      const data = await res.json();
      if (!data.success || !data.result) {
        setErrorMessage(data.error || 'AI chưa xử lý được yêu cầu này. Thầy/Cô vui lòng thử lại.');
        return;
      }

      const result = data.result;

      // Trường hợp 1: AI cần làm rõ thêm thông tin
      if (result.type === 'clarification') {
        setClarification({
          message: result.message || 'AI cần thêm thông tin để làm chính xác yêu cầu của Thầy/Cô:',
          quickOptions: result.quickOptions || [],
        });
        return;
      }

      // Trường hợp 2: AI thực hiện hành động
      if (result.type === 'action') {
        if (JSON.stringify(liveExam.current.questions) !== base) { setErrorMessage('Đề đã được sửa trong lúc AI xử lý. Hãy gửi lại yêu cầu.'); return; }
        setProposal({ result, base });
        setCommand('');
      }
    } catch (err: unknown) {
      console.error('Lỗi gọi Copilot:', err);
      setErrorMessage('Không thể kết nối đến máy chủ AI. Vui lòng kiểm tra lại mạng hoặc API Key.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter' && !isLoading) {
      handleSendCommand();
    }
  };

  return (
    <div className="bg-white dark:bg-[#1e1e1e] border border-[#dadce0] dark:border-[#3c4043] rounded-3xl p-4 sm:p-5 text-[#202124] dark:text-[#e3e3e3] shadow-xs transition-all">
      {proposal && <div className="m-3 p-3 border rounded-xl bg-amber-50 text-slate-900 text-sm" role="region" aria-label="Đề xuất AI chưa áp dụng"><p>{proposal.result.explanation || 'Đề xuất sửa đề'}</p>{proposal.result.modifiedQuestion && <AiProposalPreview question={proposal.result.modifiedQuestion} before={exam.questions.find(q => q.id === proposal.result.targetQuestionId)} />}<button type="button" onClick={acceptProposal} className="px-3 py-2 font-semibold">Áp dụng</button><button type="button" onClick={() => setProposal(null)} className="px-3 py-2">Bỏ đề xuất</button></div>}
      {/* Tiêu đề & Trạng thái */}
      <div className="flex items-center justify-between gap-2 mb-3">
        <div className="flex items-center gap-2">
          <div className="w-7 h-7 rounded-full bg-[#e8f0fe] dark:bg-[#1e2a38] border border-[#1a73e8]/30 dark:border-[#8ab4f8]/30 flex items-center justify-center">
            <Sparkles className="w-4 h-4 text-[#1a73e8] dark:text-[#8ab4f8] animate-pulse" />
          </div>
          <div>
            <h3 className="text-xs sm:text-sm font-bold text-[#202124] dark:text-[#e3e3e3] flex items-center gap-1.5">
              <span>Trợ Lý AI Biên Tập Trực Tiếp Đề Thi</span>
              <span className="text-[10px] font-semibold px-2 py-0.5 rounded-full bg-[#e8f0fe] dark:bg-[#1e2a38] text-[#1a73e8] dark:text-[#8ab4f8] border border-[#1a73e8]/30 dark:border-[#8ab4f8]/30">
                Copilot 2.0
              </span>
            </h3>
            <p className="text-[11px] text-[#5f6368] dark:text-[#9aa0a6] hidden sm:block">
              Ra lệnh bằng tiếng Việt để AI sửa bất kỳ câu nào, tăng/giảm độ khó, đổi số liệu hoặc hỏi đáp sư phạm.
            </p>
          </div>
        </div>

        {selectedQuestionIds.length > 0 && (
          <span className="text-[11px] font-semibold px-2.5 py-0.5 rounded-full bg-[#fef7e0] dark:bg-[#33250b] text-[#b06000] dark:text-[#fdd663] border border-[#feefc3] dark:border-[#4d380e] shrink-0">
            Đang nhắm tới {selectedQuestionIds.length} câu đã chọn
          </span>
        )}
      </div>

      {/* Thanh nhập lệnh AI */}
      <div className="flex items-center gap-2 bg-[#f8f9fa] dark:bg-[#242424] rounded-full p-1.5 border border-[#dadce0] dark:border-[#3c4043] focus-within:border-[#1a73e8] dark:focus-within:border-[#8ab4f8] transition-all">
        <input
          id="exam-copilot-input"
          type="text"
          value={command}
          onChange={(e) => setCommand(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder="Nhập yêu cầu: ví dụ 'đổi số liệu câu 2', 'tăng độ khó câu 1', 'chuyển câu 3 thành toán thực tế'..."
          disabled={isLoading}
          className="grow bg-transparent text-xs sm:text-sm text-[#202124] dark:text-[#e3e3e3] placeholder-[#5f6368] dark:placeholder-[#9aa0a6] px-3 py-1 outline-none disabled:opacity-50"
        />

        <button
          onClick={() => handleSendCommand()}
          disabled={isLoading || !command.trim()}
          className="flex items-center gap-1.5 px-4 py-1.5 bg-[#1a73e8] hover:bg-[#1557b0] dark:bg-[#8ab4f8] dark:hover:bg-[#aecbfa] disabled:opacity-40 text-white dark:text-[#202124] rounded-full text-xs font-semibold transition-all shadow-xs shrink-0 cursor-pointer disabled:cursor-not-allowed"
        >
          {isLoading ? (
            <>
              <RefreshCw className="w-3.5 h-3.5 animate-spin" />
              <span className="hidden sm:inline">Đang sửa...</span>
            </>
          ) : (
            <>
              <Send className="w-3.5 h-3.5" />
              <span className="hidden sm:inline">Gửi lệnh</span>
            </>
          )}
        </button>
      </div>

      {/* Gợi ý mẫu một chạm (Quick Chips) */}
      <div className="flex flex-wrap items-center gap-1.5 mt-2.5">
        <span className="text-[10px] text-[#5f6368] dark:text-[#9aa0a6] font-semibold flex items-center gap-1 mr-1">
          <Compass className="w-3 h-3" /> Gợi ý nhanh:
        </span>

        <button
          onClick={() => handleSendCommand('Đổi số liệu và tính toán lại đáp án cho câu 1')}
          disabled={isLoading}
          className="text-[11px] px-3 py-1 rounded-full bg-[#f1f3f4] dark:bg-[#282828] hover:bg-[#e8eaed] dark:hover:bg-[#333538] border border-[#dadce0] dark:border-[#3c4043] text-[#202124] dark:text-[#e3e3e3] transition-colors flex items-center gap-1 cursor-pointer"
        >
          <Binary className="w-3 h-3 text-[#1a73e8] dark:text-[#8ab4f8]" />
          <span>Đổi số liệu câu 1</span>
        </button>

        <button
          onClick={() => handleSendCommand('Nâng cấp câu 1 lên mức vận dụng có bẫy toán học')}
          disabled={isLoading}
          className="text-[11px] px-3 py-1 rounded-full bg-[#f1f3f4] dark:bg-[#282828] hover:bg-[#e8eaed] dark:hover:bg-[#333538] border border-[#dadce0] dark:border-[#3c4043] text-[#202124] dark:text-[#e3e3e3] transition-colors flex items-center gap-1 cursor-pointer"
        >
          <Flame className="w-3 h-3 text-[#b06000] dark:text-[#fdd663]" />
          <span>Tăng độ khó câu 1</span>
        </button>

        <button
          onClick={() => handleSendCommand('Đơn giản hóa câu 1 về mức độ nhận biết cơ bản')}
          disabled={isLoading}
          className="text-[11px] px-3 py-1 rounded-full bg-[#f1f3f4] dark:bg-[#282828] hover:bg-[#e8eaed] dark:hover:bg-[#333538] border border-[#dadce0] dark:border-[#3c4043] text-[#202124] dark:text-[#e3e3e3] transition-colors flex items-center gap-1 cursor-pointer"
        >
          <ArrowDownCircle className="w-3 h-3 text-[#1a73e8] dark:text-[#8ab4f8]" />
          <span>Giảm độ khó</span>
        </button>

        <button
          onClick={() => handleSendCommand('Chuyển câu 1 thành bài toán ứng dụng thực tế')}
          disabled={isLoading}
          className="text-[11px] px-3 py-1 rounded-full bg-[#f1f3f4] dark:bg-[#282828] hover:bg-[#e8eaed] dark:hover:bg-[#333538] border border-[#dadce0] dark:border-[#3c4043] text-[#202124] dark:text-[#e3e3e3] transition-colors flex items-center gap-1 cursor-pointer"
        >
          <Wand2 className="w-3 h-3 text-[#137333] dark:text-[#5bb98c]" />
          <span>Biến thành toán thực tế</span>
        </button>

        <button
          onClick={() => handleSendCommand('Tạo thêm 1 câu hỏi tương tự câu 1')}
          disabled={isLoading}
          className="text-[11px] px-3 py-1 rounded-full bg-[#f1f3f4] dark:bg-[#282828] hover:bg-[#e8eaed] dark:hover:bg-[#333538] border border-[#dadce0] dark:border-[#3c4043] text-[#202124] dark:text-[#e3e3e3] transition-colors flex items-center gap-1 cursor-pointer"
        >
          <RefreshCw className="w-3 h-3 text-[#1a73e8] dark:text-[#8ab4f8]" />
          <span>Tạo câu tương tự</span>
        </button>
      </div>

      {/* KHUNG AI HỎI LẠI ĐỂ LÀM RÕ (CLARIFICATION DIALOG) */}
      {clarification && (
        <div className="mt-3 bg-[#fef7e0] dark:bg-[#33250b] border border-[#feefc3] dark:border-[#4d380e] rounded-2xl p-3.5 text-[#b06000] dark:text-[#fdd663] animate-in fade-in slide-in-from-top-2">
          <div className="flex items-start gap-2">
            <HelpCircle className="w-4 h-4 text-[#b06000] dark:text-[#fdd663] shrink-0 mt-0.5" />
            <div className="grow">
              <p className="text-xs font-semibold mb-2">
                {clarification.message}
              </p>

              {clarification.quickOptions.length > 0 && (
                <div className="flex flex-wrap gap-1.5 mb-2.5">
                  {clarification.quickOptions.map((opt, i) => (
                    <button
                      key={i}
                      onClick={() => handleSendCommand(opt)}
                      disabled={isLoading}
                      className="text-xs font-medium px-3 py-1 rounded-full bg-white dark:bg-[#202124] hover:bg-[#f1f3f4] dark:hover:bg-[#282828] border border-[#feefc3] dark:border-[#4d380e] text-[#b06000] dark:text-[#fdd663] transition-all flex items-center gap-1 cursor-pointer"
                    >
                      <ChevronRight className="w-3 h-3" />
                      <span>{opt}</span>
                    </button>
                  ))}
                  <button
                    type="button"
                    onClick={() => {
                      const el = document.getElementById('clarification-custom-input');
                      el?.focus();
                    }}
                    className="text-xs font-medium px-3 py-1 rounded-full bg-white/50 dark:bg-[#202124]/50 border border-dashed border-[#b06000]/40 dark:border-[#fdd663]/40 text-[#b06000] dark:text-[#fdd663] transition-all flex items-center gap-1 cursor-pointer"
                  >
                    <span>✏️ Phương án khác (Tự gõ)</span>
                  </button>
                </div>
              )}

              {/* Ô TỰ GÕ PHƯƠNG ÁN RIÊNG CHO GIÁO VIÊN */}
              <div className="pt-2 border-t border-[#b06000]/20 dark:border-[#fdd663]/20 flex items-center gap-2">
                <div className="relative grow">
                  <input
                    id="clarification-custom-input"
                    type="text"
                    value={customClarificationText}
                    onChange={(e) => setCustomClarificationText(e.target.value)}
                    onKeyDown={(e) => {
                      if (e.key === 'Enter' && customClarificationText.trim() && !isLoading) {
                        handleSendCommand(customClarificationText);
                        setCustomClarificationText('');
                      }
                    }}
                    placeholder="Hoặc tự gõ phương án / yêu cầu cụ thể của Thầy/Cô vào đây..."
                    disabled={isLoading}
                    className="w-full bg-white dark:bg-[#1e1e1e] border border-[#feefc3] dark:border-[#4d380e] rounded-full pl-3 pr-7 py-1.5 text-xs text-[#202124] dark:text-[#e3e3e3] placeholder-[#5f6368] dark:placeholder-[#9aa0a6] outline-none transition-all disabled:opacity-50"
                  />
                  {customClarificationText && (
                    <button
                      type="button"
                      onClick={() => setCustomClarificationText('')}
                      className="absolute right-2.5 top-1/2 -translate-y-1/2 text-[#5f6368] dark:text-[#9aa0a6] hover:text-[#202124] dark:hover:text-[#e3e3e3] text-xs px-1 cursor-pointer"
                    >
                      ×
                    </button>
                  )}
                </div>
                <button
                  onClick={() => {
                    if (customClarificationText.trim()) {
                      handleSendCommand(customClarificationText);
                      setCustomClarificationText('');
                    }
                  }}
                  disabled={isLoading || !customClarificationText.trim()}
                  className="px-4 py-1.5 bg-[#b06000] hover:bg-[#924f00] text-white font-semibold text-xs rounded-full transition-all flex items-center gap-1 shrink-0 cursor-pointer disabled:cursor-not-allowed shadow-xs"
                >
                  <Send className="w-3.5 h-3.5" />
                  <span>Gửi</span>
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Thông báo thành công */}
      {successMessage && (
        <div className="mt-2.5 bg-[#e6f4ea] dark:bg-[#0f291e] border border-[#ceead6] dark:border-[#1e4d38] rounded-2xl px-3 py-2 text-xs font-semibold text-[#137333] dark:text-[#5bb98c] flex items-center gap-2 animate-in fade-in">
          <CheckCircle2 className="w-4 h-4 text-[#137333] dark:text-[#5bb98c] shrink-0" />
          <span>{successMessage}</span>
        </div>
      )}

      {/* Thông báo lỗi */}
      {errorMessage && (
        <div className="mt-2.5 bg-[#fce8e6] dark:bg-[#371918] border border-[#fad2cf] dark:border-[#5c2523] rounded-2xl px-3 py-2 text-xs font-semibold text-[#c5221f] dark:text-[#f28b82] flex items-center gap-2 animate-in fade-in">
          <AlertCircle className="w-4 h-4 text-[#c5221f] dark:text-[#f28b82] shrink-0" />
          <span>{errorMessage}</span>
        </div>
      )}
    </div>
  );
};

'use client';

import React, { useEffect, useRef, useState } from 'react';
import type { Exam } from '@/types/exam';
import { loadExam, persistExam } from '@/lib/exam-client';
import { dbExportDatabaseToJson } from '@/lib/db';
import { portableExamBackup } from '@/lib/portable-backup';
import { BACKUP_FILE_MAX_BYTES, parseBackupText, splitBackupFiles } from '@/lib/backup-files';

interface Props { isOpen: boolean; onClose: () => void; onLoadExam: (exam: Exam) => void; currentExam: Exam; ownerId: string }
interface Summary { permissions?: Exam['access']; id: string; title: string; subject: string; grade: number; version: number }
interface ImportReport { dryRun: boolean; errorCount: number; results: { kind: string; index: number; status: string; error?: string; canImportCopy?: boolean; copy?: boolean }[]; message: string }
type Backup = { exams: unknown[]; questions: unknown[] };

export function ExamLibraryModal({ isOpen, onClose, onLoadExam, ownerId }: Props) {
  const [exams, setExams] = useState<Summary[]>([]), [query, setQuery] = useState('');
  const [busy, setBusy] = useState(false), [message, setMessage] = useState('');
  const [pending, setPending] = useState<Backup | null>(null), [report, setReport] = useState<ImportReport | null>(null);
  const [confirmImport, setConfirmImport] = useState(false);
  const [copyConflicts, setCopyConflicts] = useState(false);
  const [preparedDownloads, setPreparedDownloads] = useState<{ url: string; name: string; examCount: number }[]>([]);
  useEffect(() => () => { for (const file of preparedDownloads) URL.revokeObjectURL(file.url); }, [preparedDownloads]);
  const upload = useRef<HTMLInputElement>(null);
  async function readList() {
    const all: Summary[] = [];
    for (let page = 1; ; page++) {
      const response = await fetch(`/api/exams?limit=100&page=${page}`, { cache: 'no-store', headers: { 'x-examcraft-user': ownerId } });
      const data = await response.json();
      if (!response.ok) throw new Error(data.error ?? 'Không tải được kho đề');
      all.push(...data.exams);
      if (page >= data.pagination.totalPages) break;
    }
    return all;
  }
  function list() { return readList().then(all => { setExams(all); return all; }); }
  const [previousOpen, setPreviousOpen] = useState(isOpen);
  if (previousOpen !== isOpen) { setPreviousOpen(isOpen); if (isOpen) setMessage(''); }
  useEffect(() => { if (isOpen) void list().catch(e => setMessage(e.message)); }, [isOpen]);
  if (!isOpen) return null;
  async function action(fn: () => Promise<void>) {
    setBusy(true); setMessage('');
    try { await fn(); } catch (error) { setMessage(error instanceof Error ? error.message : 'Chưa hoàn tất thao tác'); } finally { setBusy(false); }
  }
  function prepareDownloads(archive: Awaited<ReturnType<typeof portableExamBackup>>) {
    const files = splitBackupFiles(archive), links: typeof preparedDownloads = [];
    try { for (const file of files) links.push({ url: URL.createObjectURL(new Blob([file.text], { type: 'application/json' })), name: file.name, examCount: file.examCount }); }
    catch (error) { for (const link of links) URL.revokeObjectURL(link.url); throw error; }
    setPreparedDownloads(links);
    return files.length;
  }
  async function inspect(data: Backup, asCopies = false) {
    setConfirmImport(false);
    setCopyConflicts(false); setPending(null); setReport(null);
    const response = await fetch('/api/migration/import-legacy', { method: 'POST', headers: { 'Content-Type': 'application/json', 'x-examcraft-user': ownerId }, body: JSON.stringify({ ...data, dryRun: true, copyConflicts: asCopies }) });
    const result = await response.json(); if (!response.ok) throw new Error(result.error);
    setCopyConflicts(asCopies); setPending(data); setReport(result); setMessage('Đã xem trước. Chỉ nhập các tài liệu thuộc quyền của bạn. Nguồn cũ được giữ nguyên.');
  }
  return <div role="dialog" aria-modal="true" aria-label="Kho đề và chuyển dữ liệu cũ" className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4">
    <div className="bg-white dark:bg-[#202124] rounded-2xl p-5 max-w-4xl w-full max-h-[90vh] overflow-auto space-y-4">
      <div className="flex justify-between"><h2 className="text-lg font-bold">Kho đề trên máy chủ</h2><button onClick={onClose} aria-label="Đóng kho đề">Đóng</button></div>
      <p className="text-sm">Kho này thuộc tài khoản đang đăng nhập. Bản nháp trên máy được giữ riêng cho từng tài khoản.</p>
      <div className="flex gap-3 flex-wrap text-sm">
        <button disabled={busy} onClick={() => void action(async () => { setPreparedDownloads([]); const all = await list(); const documents = []; for (const item of all) documents.push(await loadExam(item.id, ownerId)); const backup = await portableExamBackup(documents); const parts = prepareDownloads(backup); setMessage(`Đã chuẩn bị ${parts} tệp chứa ${documents.length} đề và ${backup.embeddedImages} ảnh. Tải đủ các phần bên dưới; khi khôi phục, nhập lần lượt từng tệp. Đây không thay bản sao lưu vận hành DB và tệp.`); })}>Chuẩn bị sao lưu kèm ảnh</button>
        <button disabled={busy} onClick={() => upload.current?.click()}>Nhập tệp sao lưu</button>
        <button disabled={busy} onClick={() => void action(async () => { const old = JSON.parse(await dbExportDatabaseToJson()); const current = localStorage.getItem('examcraft_current_exam'); if (current) { const doc = JSON.parse(current); if (!old.exams.some((e: Exam) => e.id === doc.id)) old.exams.push(doc); } await inspect({ exams: old.exams ?? [], questions: old.questions ?? [] }); })}>Xem dữ liệu cũ trên trình duyệt</button>
        <input ref={upload} aria-label="Chọn tệp sao lưu JSON" type="file" accept=".json,application/json" className="hidden" onChange={event => { const file = event.target.files?.[0]; if (file) { setPending(null); setReport(null); setConfirmImport(false); void action(async () => { if (file.size > BACKUP_FILE_MAX_BYTES) throw Error('Tệp vượt 30 MB. Hãy chọn từng phần sao lưu để nhập.'); await inspect(parseBackupText(await file.text())); }); } event.target.value = ''; }} />
      </div>
      {message && <p role="status" className="text-sm bg-blue-50 dark:bg-slate-800 p-3 rounded">{message}</p>}
      {preparedDownloads.map((file, index) => <a key={file.url} href={file.url} download={file.name} className="mr-2 inline-block rounded-lg bg-blue-600 px-4 py-2 text-sm font-semibold text-white">{preparedDownloads.length === 1 ? 'Tải tệp sao lưu đã chuẩn bị' : `Tải phần ${index + 1}/${preparedDownloads.length} (${file.examCount} đề)`}</a>)}
      {report && <section className="border rounded p-3 text-sm space-y-2">
        <h3 className="font-semibold">{report.dryRun ? 'Xem trước bản nhập' : 'Kết quả nhập'}</h3>
        <p>{report.results.filter(r => r.status === (report.dryRun ? 'ready' : 'imported')).length} {report.dryRun ? 'mục sẵn sàng' : 'mục vừa nhập'}; {report.results.filter(r => r.status === 'already_imported').length} mục đã chuyển trước đó; {report.errorCount} mục cần xử lý.</p>
        {report.results.filter(r => r.error).map(r => <p key={`${r.kind}-${r.index}`}>{r.kind === 'exam' ? 'Đề' : 'Câu'} {r.index + 1}: {r.error}</p>)}
        {report.dryRun && pending && report.results.some(r => r.canImportCopy) && <div><p>Có bản khác nội dung hoặc chưa đủ dấu đối chiếu. Thầy cô có thể giữ chúng thành bản sao riêng; bản đang lưu không bị thay đổi.</p><button disabled={busy} onClick={() => void action(() => inspect(pending, true))} className="font-semibold underline">Xem trước các bản sao riêng</button></div>}
        {report.results.some(r => r.copy) && <p>{report.results.filter(r => r.copy && r.status === (report.dryRun ? 'ready' : 'imported')).length} bản sao riêng {report.dryRun ? 'sẽ được tạo khi xác nhận nhập' : 'vừa được tạo'}. Các bản đang lưu được giữ nguyên.</p>}
        {pending && report.dryRun && <div className="space-y-2"><label className="flex items-start gap-2"><input type="checkbox" checked={confirmImport} onChange={e => setConfirmImport(e.target.checked)} />Tôi có quyền sử dụng các tài liệu này và muốn nhập vào tài khoản hiện tại.</label><button disabled={busy || !confirmImport} onClick={() => void action(async () => { const response = await fetch('/api/migration/import-legacy', { method: 'POST', headers: { 'Content-Type': 'application/json', 'x-examcraft-user': ownerId }, body: JSON.stringify({ ...pending, dryRun: false, copyConflicts }) }); const data = await response.json(); if (!response.ok) throw new Error(data.error); setReport(data); setMessage(data.message); await list(); })} className="font-semibold underline disabled:opacity-50">Nhập các mục hợp lệ</button></div>}
      </section>}
      <input value={query} onChange={e => setQuery(e.target.value)} placeholder="Tìm tên đề" aria-label="Tìm tên đề" className="border rounded p-2 w-full" />
      <ul className="space-y-2">{exams.filter(e => e.title.toLowerCase().includes(query.toLowerCase())).map(item => <li key={item.id} className="border rounded p-3 flex items-center justify-between gap-3">
        <div><strong>{item.title}</strong><p className="text-sm">{item.subject} · Lớp {item.grade}</p></div>
        <div className="flex gap-3 text-sm">
          <button disabled={busy} onClick={() => void action(async () => { onLoadExam(await loadExam(item.id, ownerId)); onClose(); })}>Mở</button>
          <button disabled={busy} onClick={() => void action(async () => { const source = await loadExam(item.id, ownerId); await persistExam({ ...source, id: `draft_${crypto.randomUUID()}`, serverId: undefined, version: undefined, metadata: { ...source.metadata, title: `${source.metadata.title} (Bản sao)` } }, ownerId); await list(); })}>Nhân bản</button>
          <button disabled={busy || item.permissions?.canManage === false} onClick={() => void action(async () => { if (!confirm('Chuyển đề vào thùng rác? Có thể khôi phục tại trang quản lý.')) return; const response = await fetch(`/api/exams/${item.id}`, { method: 'DELETE', headers: { 'If-Match': String(item.version), 'x-examcraft-user': ownerId } }); const data = await response.json(); if (!response.ok) throw new Error(data.error); await list(); })}>Thùng rác</button>
        </div>
      </li>)}</ul>
      {!exams.length && <p>Chưa có đề đã lưu trên máy chủ.</p>}
    </div>
  </div>;
}

