                      Thầy/Cô có thể bắt đầu tạo đề bằng cách nhờ AI sinh tự động theo ma trận hoặc tự thêm các câu hỏi thủ công.
                    </p>
                    <div className="flex items-center justify-center gap-3">
                      <button
                        onClick={() => setIsGenerateModalOpen(true)}
                        className="px-4 py-2 bg-[#1a73e8] hover:bg-[#1557b0] text-white rounded-full text-xs font-semibold shadow-xs cursor-pointer flex items-center gap-1.5 transition-colors"
                      >
                        <Sparkles className="w-3.5 h-3.5" />
                        <span>Sinh đề bằng AI</span>
                      </button>
                      <button
                        onClick={handleAddQuestion}
                        className="px-4 py-2 bg-white dark:bg-[#282828] border border-[#dadce0] dark:border-[#3c4043] hover:bg-[#f8f9fa] dark:hover:bg-[#303134] text-[#3c4043] dark:text-[#e3e3e3] rounded-full text-xs font-semibold shadow-2xs cursor-pointer flex items-center gap-1.5 transition-colors"
                      >
                        <Plus className="w-3.5 h-3.5" />
                        <span>Thêm câu hỏi mới</span>
                      </button>
                    </div>
                  </div>
                )}
              </div>

              {/* Thanh tác vụ hàng loạt nổi cố định ở dưới (Floating Batch Action Bar) */}
              {selectedQuestionIds.length > 0 && (
                <div className="fixed bottom-6 left-1/2 -translate-x-1/2 z-40 bg-[#202124]/95 dark:bg-[#1e1e1e]/95 backdrop-blur-md text-white px-5 py-3 rounded-full shadow-2xl border border-[#dadce0]/30 dark:border-[#3c4043] flex items-center gap-3 animate-in fade-in slide-in-from-bottom-5">
                  <span className="text-xs font-bold text-[#8ab4f8] bg-[#1e2a38] px-2.5 py-1 rounded-full border border-[#2a3f58]">
                    Đã chọn {selectedQuestionIds.length} câu
                  </span>

                  <div className="h-4 w-px bg-[#3c4043]" />

                  {/* Nút Gộp câu */}
                  <button
                    onClick={handleMergeSelected}
                    disabled={selectedQuestionIds.length < 2}
                    title={selectedQuestionIds.length < 2 ? "Chọn ít nhất 2 câu để gộp thành 1 câu tự luận" : "Gộp các câu đã chọn thành 1 câu tự luận tổng hợp có nhiều ý a, b, c..."}
                    className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-semibold rounded-full bg-[#1a73e8] hover:bg-[#1557b0] disabled:opacity-40 disabled:cursor-not-allowed transition-all shadow-xs cursor-pointer"
                  >
                    <Link2 className="w-3.5 h-3.5" />
                    <span>Gộp thành 1 câu tự luận</span>
                  </button>

                  {/* Nút Xóa các câu đã chọn */}
                  <button
                    onClick={handleBatchDelete}
                    title="Xóa các câu hỏi đã chọn"
                    className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-semibold rounded-full bg-rose-600 hover:bg-rose-500 text-white transition-all shadow-xs cursor-pointer"
                  >
                    <Trash2 className="w-3.5 h-3.5" />
                    <span>Xóa ({selectedQuestionIds.length})</span>
                  </button>

                  <div className="h-4 w-px bg-[#3c4043]" />

                  {/* Nút Hủy chọn */}
                  <button
                    onClick={() => setSelectedQuestionIds([])}
                    title="Hủy chọn tất cả"
                    className="p-1.5 text-[#9aa0a6] hover:text-[#e3e3e3] rounded-full hover:bg-[#303134] transition-colors cursor-pointer"
                  >
                    <X className="w-4 h-4" />
                  </button>
                </div>
              )}
            </fieldset>

            {/* CỘT PHẢI: KHUNG XEM TRƯỚC BẢN IN A4 (6 Cột trên màn hình lớn) */}
            <section
              className={`a4-preview-section lg:col-span-6 sticky top-0 h-[calc(100vh-6rem)] ${
                mobileTab === 'editor' ? 'hidden lg:block' : 'block'
              } print:!block print:!static print:!h-auto print:!w-full print:!overflow-visible`}
            >
              <A4Preview exam={exam} />
            </section>
          </main>
        </div>

        {/* ZONE 3: THANH MENU DỌC BÊN PHẢI (GOOGLE GEMINI COMPANION RAIL) */}
        {canEdit && <RightCompanionRail
          key={`${currentUser.id}:${exam.id}`}
          ownerId={currentUser.id}
          onSubmitCopilot={submission => setExam(previous => applyCopilotSubmission(previous, submission, currentUser.id))}
          isExpanded={isCopilotOpen}
          onToggleExpand={() => setIsCopilotOpen(!isCopilotOpen)}
          exam={exam}
          selectedQuestionIds={selectedQuestionIds}
          externalCommand={copilotCommand}
          onOpenMatrixModal={() => setIsMatrixTabActive(true)}
          onOpenShuffleModal={() => setIsShuffleModalOpen(true)}
          onOpenHeaderSettingsModal={() => setIsHeaderModalOpen(true)}
        />}
      </div>

      {/* CÁC MODALS NGHIỆP VỤ */}
      {presentationOpen && <ExamPresentation exam={exam} onClose={() => setPresentationOpen(false)} />}
      {collaborationOpen && exam.serverId && <div role="dialog" aria-modal="true" aria-label="Cộng tác và lịch sử" className="fixed inset-0 z-50 bg-black/50 p-4 flex items-center justify-center"><div className="w-full max-w-3xl max-h-[90vh] overflow-auto bg-white dark:bg-[#202124] rounded-2xl p-5"><button type="button" className="float-right px-3 py-2" onClick={() => setCollaborationOpen(false)}>Đóng</button><ExamCollaboratorsPanel key={`${exam.serverId}-${currentUser.id}`} examId={exam.serverId} expectedUserId={currentUser.id} onRestored={document => { acceptServerDocument(document); }} beforeRestore={() => { if (saveState !== 'saved') { alert('Hãy lưu xong hoặc giữ bản nháp thành đề mới trước khi khôi phục lịch sử.'); return false; } return true; }} /></div></div>}
      <ApiKeyModal ownerId={currentUser.id} key={currentUser.id}
        isOpen={isApiKeyModalOpen}
        onClose={() => setIsApiKeyModalOpen(false)}
        onKeyUpdated={checkUserKeys}
      />

      <GenerateModal
        key={`${exam.metadata.subject}-${exam.metadata.grade}-${exam.metadata.knowledgePackage?.id ?? ''}-${exam.metadata.knowledgePackage?.revision ?? ''}`}
        context={exam.metadata}
        documentStamp={isGenerateModalOpen ? generationDocumentStamp(exam) : ''}
        expectedUserId={currentUser.id}
        replacesDocument
        isOpen={isGenerateModalOpen}
        onClose={() => setIsGenerateModalOpen(false)}
        onExamGenerated={(newExam, baseStamp) => setExam(previous => applyGeneratedDraft(previous, newExam, baseStamp))}
        apiKey=""
      />

      <ShuffleModal
        isOpen={isShuffleModalOpen}
        onClose={() => setIsShuffleModalOpen(false)}
        baseExam={exam}
        onSelectVariant={(variantExam) => setExam(previous => ({ ...variantExam, id: previous.id, serverId: previous.serverId, version: previous.version, access: previous.access }))}
      />

      <ImportModal
        ownerId={currentUser.id}
        documentId={exam.id}
        context={{ subject: exam.metadata.subject, grade: exam.metadata.grade }}
        isOpen={isImportModalOpen}
        onClose={() => setIsImportModalOpen(false)}
        onImportQuestions={(newQuestions, context) => {
          setExam((prev) => prev.id !== exam.id || prev.access?.canEdit === false ? prev : ({
            ...prev,
            questions: [...prev.questions, ...newQuestions],
            passages: [...(prev.passages ?? []), ...(context.passages ?? [])],
            updatedAt: new Date().toISOString(),
          }));
        }}
        apiKey=""
      />

      <ExamLibraryModal
        ownerId={currentUser.id}
        isOpen={isLibraryModalOpen}
        onClose={() => setIsLibraryModalOpen(false)}
        onLoadExam={(loadedExam) => { window.location.assign(`/editor/${loadedExam.id}`); }}
        currentExam={exam}
      />

      <HeaderSettingsModal
        documentId={exam.id}
        ownerId={currentUser.id}
        isOpen={isHeaderModalOpen}
        onClose={() => setIsHeaderModalOpen(false)}
        metadata={exam.metadata}
        onSaveMetadata={(submission) => setExam(previous => applyHeaderSubmission(previous, submission))}
      />

      <QuestionBankModal ownerId={currentUser.id} key={currentUser.id}
        isOpen={isQuestionBankModalOpen}
        onClose={() => setIsQuestionBankModalOpen(false)}
        onInsertQuestion={(q, passage) => {
          const { passage: _bankPassage, passageUnavailable: _unavailable, ...question } = q as BankQuestion;
          const newQuestion: Question = {
            ...question,
            id: crypto.randomUUID(),
          };
          setExam(prev => {
            const passages = [...(prev.passages ?? [])];
            if (passage) {
              const existing = passages.find(p => p.id === passage.id);
              const id = existing && JSON.stringify(existing) !== JSON.stringify(passage) ? crypto.randomUUID() : passage.id;
              if (!passages.some(p => p.id === id)) passages.push({ ...passage, id });
              newQuestion.passageId = id;
            }
            return { ...prev, passages, questions: [...prev.questions, newQuestion], updatedAt: new Date().toISOString() };
          });
        }}
      />

      <ShareModal
        key={`share:${currentUser.id}:${exam.id}`}
        ownerId={currentUser.id}
        onEnsureSaved={ensureSaved}
        isOpen={isShareModalOpen}
        onClose={() => setIsShareModalOpen(false)}
        exam={exam}
        onCloudSyncSuccess={() => { /* Server acknowledgement is tracked by the save controller. */ }}
      />

      <StudentResultsModal
        isOpen={isResultsModalOpen}
        onClose={() => setIsResultsModalOpen(false)}
        exam={exam}
        onOpenShareModal={() => {
          setIsResultsModalOpen(false);
          setIsShareModalOpen(true);
        }}
      />

      <AiLearningModal
        isOpen={isAiLearningModalOpen}
        onClose={() => setIsAiLearningModalOpen(false)}
        currentUser={currentUser}
      />
    </div>
  );
};
export default ExamWorkspace;

'use client';

import { useState } from 'react';
import type { Figure } from '@/types/exam';
import { VariationTable, type VariationTableData } from './VariationTable';
import { FunctionPlot, type FunctionPlotData } from './FunctionPlot';
import { compileMathExpression } from '@/lib/math-expression';

export function FigureView({ figure, forceLight = false }: { figure: Figure; forceLight?: boolean }) {
  const [failedSource, setFailedSource] = useState('');
  const data = figure.data && typeof figure.data === 'object' ? figure.data as Record<string, unknown> : {};
  const source = typeof data.url === 'string' ? data.url : figure.renderedBase64 ?? (typeof figure.data === 'string' ? figure.data : '');
  const missing = (message: string) => <p role="note" className="border border-amber-400 rounded p-2 text-sm">{message}</p>;
  let content;
  if (figure.kind === 'variation_table') content = <VariationTable data={figure.data as VariationTableData} forceLight={forceLight} />;
  else if (figure.kind === 'function_plot') content = compileMathExpression(data.expression) ? <FunctionPlot data={figure.data as FunctionPlotData} forceLight={forceLight} /> : missing('Đồ thị chưa có biểu thức hợp lệ. Hãy sửa dữ liệu hình.');
  else if (source && /^(data:image\/|https?:\/\/|\/)/i.test(source) && failedSource !== source) content = <img src={source} alt={figure.caption || 'Hình của câu hỏi'} onError={() => setFailedSource(source)} className="max-h-64 max-w-full object-contain mx-auto bg-white rounded border" />;
  else content = missing('Hình chưa có tệp ảnh hoặc không tải được. Dữ liệu gốc vẫn được giữ; hãy bổ sung ảnh.');
  return <figure className="my-2 overflow-x-auto">{content}{figure.caption && <figcaption className="text-xs italic mt-1 text-center">{figure.caption}</figcaption>}</figure>;
}

'use client';

import React, { useState } from 'react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { 
  GraduationCap, 
  Menu, 
  CloudCheck, 
  CloudUpload, 
  Sun, 
  Moon, 
  Key, 
  LogOut, 
  ShieldCheck, 
  ChevronDown,
