export const Header: React.FC<HeaderProps> = ({
  canEdit = true,
  examTitle,
  onUpdateTitle,
  isSidebarCollapsed,
  onToggleSidebar,
  onOpenApiKeyModal,
  hasActiveKey,
  keyCount = 0,
  keyErrorCount = 0,
  quota = { dailyLimit: 100, usedToday: 0, remaining: 100 },
