            className={`p-2 rounded-full transition-colors cursor-pointer flex items-center gap-1.5 text-xs font-medium ${
              isCopilotOpen
                ? 'bg-[#e8f0fe] dark:bg-[#1e2a38] text-[#1a73e8] dark:text-[#8ab4f8] border border-blue-200 dark:border-[#3c4043]'
                : 'text-[#5f6368] hover:text-[#202124] dark:text-[#9aa0a6] dark:hover:text-[#e3e3e3] hover:bg-[#f1f3f4] dark:hover:bg-[#282828]'
            }`}
          >
            <Sparkles className="w-4 h-4 text-amber-500 shrink-0" />
            <span className="hidden md:inline">Gemini AI</span>
          </button>
        )}

        {/* Nút bật/tắt Dark Mode */}
        <button
          onClick={toggleTheme}
          title={theme === 'dark' ? 'Chuyển sang chế độ Sáng (Màu trắng Google)' : 'Chuyển sang chế độ Tối (Dark Mode)'}
          className="p-2 rounded-full text-[#5f6368] hover:text-[#202124] dark:text-[#9aa0a6] dark:hover:text-[#e3e3e3] hover:bg-[#f1f3f4] dark:hover:bg-[#282828] transition-colors cursor-pointer"
        >
          {theme === 'dark' ? <Sun className="w-4 h-4 text-amber-400" /> : <Moon className="w-4 h-4 text-[#5f6368]" />}
        </button>

        {/* Nút Trạng thái Khóa AI cá nhân (Badge Google Minimalist) */}
        <button
          onClick={onOpenApiKeyModal}
          title={
            !hasActiveKey
              ? 'Tài khoản chưa có API Key: Nhấn để thêm khóa cá nhân'
              : keyErrorCount > 0
              ? `Có ${keyErrorCount} khóa bị lỗi hoặc hết lượt (429)!`
              : `Khóa AI Google Gemini: ${keyCount} khóa đang hoạt động tốt`
          }
          className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-medium transition-all border cursor-pointer shadow-2xs ${
            !hasActiveKey
              ? 'bg-amber-50 dark:bg-amber-950/40 text-amber-800 dark:text-amber-300 border-amber-200 dark:border-amber-800 hover:bg-amber-100'
              : keyErrorCount > 0
              ? 'bg-rose-50 dark:bg-rose-950/40 text-rose-800 dark:text-rose-300 border-rose-200 dark:border-rose-800 hover:bg-rose-100'
              : 'bg-white dark:bg-[#282828] text-[#3c4043] dark:text-[#e3e3e3] border-[#dadce0] dark:border-[#3c4043] hover:bg-[#f8f9fa] dark:hover:bg-[#303134]'
          }`}
        >
          <Key className="w-3.5 h-3.5 text-[#5f6368] dark:text-[#9aa0a6]" />
          <span className="hidden sm:inline">Khóa AI</span>
          {keyCount > 0 && <span className="font-mono text-[11px] font-semibold">({keyCount})</span>}
          <span
            className={`w-2 h-2 rounded-full ${
              !hasActiveKey
                ? 'bg-amber-500 animate-pulse'
                : keyErrorCount > 0
                ? 'bg-rose-500 animate-pulse'
                : 'bg-emerald-500'
            }`}
          />
        </button>

        {/* Avatar & Dropdown Menu với Bảng Theo Dõi Khóa AI Trực Quan */}
        {currentUser ? (
          <div className="relative">
            <button
              onClick={() => setIsUserMenuOpen(!isUserMenuOpen)}
              className="flex items-center gap-2 py-1 px-1.5 sm:px-2 rounded-full hover:bg-[#f1f3f4] dark:hover:bg-[#282828] transition-colors cursor-pointer"
            >
              <div className="w-7 h-7 rounded-full bg-[#202124] dark:bg-[#282828] text-white dark:text-[#8ab4f8] border border-transparent dark:border-[#3c4043] flex items-center justify-center text-xs font-bold shadow-xs">
                {currentUser.name ? currentUser.name.charAt(0).toUpperCase() : 'U'}
              </div>
              <ChevronDown className="w-3.5 h-3.5 text-[#5f6368] dark:text-[#9aa0a6] hidden sm:block" />
            </button>

            {isUserMenuOpen && (
              <>
                <div 
                  className="fixed inset-0 z-40" 
                  onClick={() => setIsUserMenuOpen(false)} 
                />
                <div className="absolute right-0 mt-2 w-72 bg-white dark:bg-[#1e1e1e] border border-[#dadce0] dark:border-[#3c4043] rounded-3xl shadow-2xl z-50 p-2.5 text-xs divide-y divide-[#f1f3f4] dark:divide-[#3c4043] animate-in fade-in zoom-in-95 duration-100">
                  {/* THÔNG TIN NGƯỜI DÙNG */}
                  <div className="p-2">
                    <p className="font-bold text-[#202124] dark:text-[#e3e3e3] text-sm truncate">{currentUser.name}</p>
                    <p className="text-[11px] text-[#5f6368] dark:text-[#9aa0a6] truncate">{currentUser.email}</p>
                    <span className="inline-block mt-1 px-2 py-0.5 rounded-full text-[10px] font-bold uppercase tracking-wider bg-[#e8f0fe] dark:bg-[#1e2a38] text-[#1a73e8] dark:text-[#8ab4f8]">
                      {currentUser.role === 'SUPER_ADMIN' ? 'Quản trị viên' : 'Giáo viên'}
                    </span>
                  </div>

                  {/* KHỐI THEO DÕI TRẠNG THÁI KHÓA AI & HẠN MỨC */}
                  <div className="py-2.5">
                    <div className="p-3 bg-[#f8f9fa] dark:bg-[#282828]/60 rounded-2xl border border-[#dadce0] dark:border-[#3c4043] space-y-2">
                      <div className="flex items-center justify-between">
                        <span className="text-[11px] font-bold text-[#3c4043] dark:text-[#e3e3e3] flex items-center gap-1.5">
                          <Activity className="w-3.5 h-3.5 text-[#1a73e8] dark:text-[#8ab4f8]" />
                          <span>Kho Khóa AI Của Bạn</span>
                        </span>
                        <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${
                          !hasActiveKey
                            ? 'bg-amber-100 text-amber-800 dark:bg-amber-950/60 dark:text-amber-300'
                            : keyErrorCount > 0
                            ? 'bg-rose-100 text-rose-800 dark:bg-rose-950/60 dark:text-rose-300'
                            : 'bg-emerald-100 text-emerald-800 dark:bg-emerald-950/60 dark:text-emerald-300'
                        }`}>
                          {!hasActiveKey 
                            ? 'Chưa có key' 
                            : keyErrorCount > 0 
                            ? `${keyErrorCount} key lỗi/429` 
                            : `${keyCount} key sẵn sàng`}
                        </span>
                      </div>

                      {/* Thanh tiến trình hạn mức hôm nay */}
                      <div className="space-y-1">
                        <div className="flex items-center justify-between text-[11px] text-[#5f6368] dark:text-[#9aa0a6]">
                          <span>Đã dùng hôm nay:</span>
                          <span className="font-bold text-[#202124] dark:text-[#e3e3e3]">{quota.usedToday} / {quota.dailyLimit} lượt</span>
                        </div>
                        <div className="w-full bg-[#dadce0] dark:bg-[#3c4043] h-1.5 rounded-full overflow-hidden">
                          <div 
                            className={`h-full rounded-full transition-all duration-300 ${
                              usagePercent > 80 ? 'bg-rose-500' : 'bg-[#1a73e8] dark:bg-[#8ab4f8]'
                            }`}
                            style={{ width: `${usagePercent}%` }}
                          />
                        </div>
                        <div className="text-[10px] text-emerald-600 dark:text-emerald-400 flex items-center justify-between">
                          <span>Còn lại: {quota.remaining} lượt</span>
                          <span className="text-[#5f6368] dark:text-[#9aa0a6] font-sans">({usagePercent}%)</span>
                        </div>
                      </div>

                      {/* Cảnh báo trạng thái */}
                      {!hasActiveKey ? (
                        <p className="text-[11px] text-amber-700 dark:text-amber-300 flex items-center gap-1.5 pt-0.5">
                          <AlertCircle className="w-3.5 h-3.5 shrink-0 text-amber-600" />
                          <span>Chưa thêm khóa AI cá nhân!</span>
                        </p>
                      ) : keyErrorCount > 0 ? (
                        <p className="text-[11px] text-rose-600 dark:text-rose-400 flex items-center gap-1.5 pt-0.5">
                          <AlertCircle className="w-3.5 h-3.5 shrink-0 text-rose-600" />
                          <span>Có khóa đang chạm hạn mức 429!</span>
                        </p>
                      ) : (
                        <p className="text-[11px] text-emerald-700 dark:text-emerald-300 flex items-center gap-1.5 pt-0.5">
                          <CheckCircle2 className="w-3.5 h-3.5 shrink-0 text-emerald-600" />
                          <span>Tự động xoay tua đa khóa sẵn sàng</span>
                        </p>
                      )}

                      {/* Nút bấm mở nhanh Modal Quản lý API Key */}
                      <button
                        onClick={() => {
                          setIsUserMenuOpen(false);
                          onOpenApiKeyModal();
                        }}
                        className="w-full mt-1 py-2 px-3 bg-[#202124] hover:bg-[#303134] text-white dark:bg-[#282828] dark:text-[#e3e3e3] dark:hover:bg-[#303134] dark:border dark:border-[#3c4043] rounded-full font-medium text-xs flex items-center justify-center gap-1.5 shadow-2xs transition-colors cursor-pointer"
                      >
                        <Key className="w-3.5 h-3.5" />
                        <span>Quản lý & Kiểm tra Khóa AI</span>
                      </button>
                    </div>
                  </div>

                  {currentUser.role === 'SUPER_ADMIN' && (
                    <div className="py-1">
                      <Link
                        href="/admin/users"
                        onClick={() => setIsUserMenuOpen(false)}
                        className="flex items-center gap-2 px-2.5 py-1.5 rounded-full text-[#3c4043] dark:text-[#e3e3e3] hover:bg-[#f1f3f4] dark:hover:bg-[#282828] transition-colors"
                      >
                        <ShieldCheck className="w-4 h-4 text-[#1a73e8] dark:text-[#8ab4f8]" />
                        <span>Quản trị người dùng</span>
                      </Link>
                    </div>
                  )}

                  <div className="pt-1">
                    <button
                      onClick={handleLogout}
                        disabled={loggingOut}
                      className="w-full flex items-center gap-2 px-2.5 py-1.5 rounded-full text-rose-600 dark:text-rose-400 hover:bg-rose-50 dark:hover:bg-rose-950/40 transition-colors cursor-pointer"
                    >
                      <LogOut className="w-4 h-4" />
                      <span>Đăng xuất tài khoản</span>
                    </button>
                      {logoutError && <p role="alert" className="mt-2 text-xs text-red-600 dark:text-red-300">{logoutError}</p>}
                  </div>
                </div>
              </>
            )}
          </div>
        ) : (
          <Link
            href="/login"
            className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-bold text-white bg-blue-600 hover:bg-blue-700 shadow-xs transition-colors"
          >
            <UserIcon className="w-3.5 h-3.5" />
            <span>Đăng nhập</span>
          </Link>
        )}
      </div>
    </header>
  );
};

'use client';

import React, { useState, useRef, useEffect } from 'react';
import { Question, Subject, Passage } from '@/types/exam';
import { getCatalogSubjects } from '@/lib/education-catalog';
import { parseExTestLatex, parseRawVietnameseDocument } from '@/lib/exam-parser';
import { MathRenderer } from './MathRenderer';
import { accountFetch } from '@/lib/account-fetch';
import { isAccountFailure, RequestGate } from '@/lib/template-request-context';
import { 
  X, 
  FileText, 
  Sparkles, 
  Code, 
  Upload, 
  Check, 
  AlertCircle, 
  RefreshCw,
  Plus,
  Image as ImageIcon,
  FileCode,
  Trash2,
  ZoomIn,
  CheckCircle2,
  Eye,
  Layers
} from 'lucide-react';

interface ImportModalProps {
  ownerId: string;
  documentId?: string;
  isOpen: boolean;
  onClose: () => void;
  onImportQuestions: (questions: Question[], context: { subject: Subject; grade: number; passages?: Passage[] }) => void;
  context?: { subject: Subject; grade: number };
  apiKey: string;
}

type ImportSourceType = 'image' | 'word' | 'text' | 'latex';

export const ImportModal: React.FC<ImportModalProps> = props => <ImportModalContent key={`${props.ownerId}:${props.documentId ?? 'new'}`} {...props} />;
const ImportModalContent: React.FC<ImportModalProps> = ({
  ownerId,
  isOpen,
  onClose,
  onImportQuestions,
  apiKey,
  context,
}) => {
  const [importGrade, setImportGrade] = useState(context?.grade ?? 0);
  const [importSubject, setImportSubject] = useState<Subject | ''>(context?.subject ?? '');
  const [sourceType, setSourceType] = useState<ImportSourceType>('image');

  // State cho ảnh
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [imageFileName, setImageFileName] = useState<string>('');

  // State cho Word & Text & LaTeX
  const [rawText, setRawText] = useState('');
  const [wordFileName, setWordFileName] = useState<string>('');
  const [wordFile, setWordFile] = useState<File | null>(null);

  // State kết quả bóc tách
  const [parsedQuestions, setParsedQuestions] = useState<Question[]>([]);
  const [parsedPassages, setParsedPassages] = useState<Passage[]>([]);
  const [importWarnings, setImportWarnings] = useState<string[]>([]);
  const parseRequest = useRef(0);
  const requestGate = useRef<RequestGate | null>(null);
  const imageRead = useRef(0), textRead = useRef(0);
  const readContext = useRef(0);
  const [accountLocked, setAccountLocked] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [statusMessage, setStatusMessage] = useState<string | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const wordInputRef = useRef<HTMLInputElement>(null);
  const [previousInput, setPreviousInput] = useState({ sourceType, rawText, selectedImage, wordFile, isOpen });
  if (previousInput.sourceType !== sourceType || previousInput.rawText !== rawText || previousInput.selectedImage !== selectedImage || previousInput.wordFile !== wordFile || previousInput.isOpen !== isOpen) {
    setPreviousInput({ sourceType, rawText, selectedImage, wordFile, isOpen });
    setParsedQuestions([]); setParsedPassages([]); setImportWarnings([]);
    setStatusMessage(null); setErrorMessage(null); setIsLoading(false);
  }
  useEffect(() => {
    const gate = new RequestGate(); requestGate.current = gate;
    parseRequest.current += 1;
    return () => { gate.dispose(); parseRequest.current++; };
  }, [sourceType, rawText, selectedImage, wordFile, isOpen]);
  useEffect(() => () => { readContext.current++; imageRead.current++; textRead.current++; }, [isOpen, sourceType]);

  if (!isOpen) return null;
  const handleClose = () => { requestGate.current?.dispose(); parseRequest.current++; imageRead.current++; textRead.current++; onClose(); };

  // Xử lý chọn ảnh
  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setImageFileName(file.name);
    setSelectedImage(null);
    setErrorMessage(null);
    setStatusMessage(null);

    const reader = new FileReader();
    const readId = ++imageRead.current, contextId = readContext.current;
    reader.onload = (event) => {
      if (readId !== imageRead.current || contextId !== readContext.current) return;
      setSelectedImage(event.target?.result as string);
    };
    reader.readAsDataURL(file);
  };

  // Xử lý chọn file Word docx
  const handleWordSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setWordFile(file);
    setWordFileName(file.name);
    setErrorMessage(null);
    setStatusMessage(null);
  };

  // Xử lý đọc file text/latex
  const handleTextFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    setRawText('');
    const readId = ++textRead.current, contextId = readContext.current;
    reader.onload = (event) => {
      if (readId !== textRead.current || contextId !== readContext.current) return;
      const content = event.target?.result as string;
      if (content) {
        setRawText(content);
        if (content.includes('\\begin{ex}') || content.includes('\\choice')) {
          setSourceType('latex');
        }
      }
    };
    reader.readAsText(file);
  };

  // Bắt đầu quá trình bóc tách
  const handleStartParsing = async () => {
    if (accountLocked) return;
    const gate = requestGate.current, token = gate?.begin();
    if (!gate || !token) return;
    const requestId = ++parseRequest.current;
    setIsLoading(true);
    setStatusMessage(null);
    setErrorMessage(null);

    const send = async (url: string, init: RequestInit) => {
      const res = await accountFetch(ownerId, url, { ...init, signal: token.signal });
      const data = await res.json();
      if (token.isLive() && isAccountFailure(res.status, data)) {
        gate.lock(); setAccountLocked(true); setIsLoading(false);
        setErrorMessage('Phiên hoặc tài khoản đã thay đổi. Nguồn đang nhập vẫn giữ; hãy tải lại trang bằng đúng tài khoản.');
      }
      return { res, data };
    };

    try {
      if (sourceType === 'image') {
        if (!selectedImage) {
          setErrorMessage('Vui lòng chọn hoặc kéo thả một hình ảnh đề thi.');
          setIsLoading(false);
          return;
        }

        const { res, data } = await send('/api/ocr-exam-image', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            imageBase64: selectedImage,
            userApiKey: apiKey,
          }),
        });

        if (!token.isLive() || requestId !== parseRequest.current) return;
        if (res.ok && data.success && Array.isArray(data.questions)) {
          setParsedQuestions(data.questions);
          setParsedPassages(data.passages ?? []);
          setImportWarnings(data.warnings ?? []);
          setStatusMessage(`AI Vision đã nhận diện thành công ${data.questions.length} câu hỏi từ ảnh chụp!`);
        } else {
          setErrorMessage(data.error || 'Không thể bóc tách câu hỏi từ ảnh.');
        }
      } else if (sourceType === 'word') {
        if (!wordFile) {
          setErrorMessage('Vui lòng chọn file Word (.docx) của bạn.');
          setIsLoading(false);
          return;
        }

        const formData = new FormData();
        formData.append('file', wordFile);
        if (apiKey) formData.append('userApiKey', apiKey);

        const { res, data } = await send('/api/parse-docx', {
          method: 'POST',
          body: formData,
        });

        if (!token.isLive() || requestId !== parseRequest.current) return;
        if (res.ok && data.success && Array.isArray(data.questions)) {
          setParsedQuestions(data.questions);
          setParsedPassages(data.passages ?? []);
          setImportWarnings(data.warnings ?? []);
          setStatusMessage(`Đã bóc tách thành công ${data.questions.length} câu hỏi từ file Word!`);
        } else {
          setErrorMessage(data.error || 'Không thể phân rã nội dung từ file Word.');
        }
      } else if (sourceType === 'latex') {
        if (!rawText.trim()) {
          setErrorMessage('Vui lòng dán mã LaTeX câu hỏi.');
          setIsLoading(false);
          return;
        }

        const questions = parseExTestLatex(rawText);
        if (questions.length > 0) {
          setParsedQuestions(questions);
          setStatusMessage(`Thành công! Đã bóc tách ${questions.length} câu hỏi chuẩn LaTeX EX_Test.`);
        } else {
          setErrorMessage('Không tìm thấy cấu trúc \\begin{ex}...\\end{ex} hợp lệ.');
        }
      } else {
        // Text thô AI
        if (!rawText.trim()) {
          setErrorMessage('Vui lòng dán văn bản đề thi thô.');
          setIsLoading(false);
          return;
        }

        const { res, data } = await send('/api/parse-exam-text', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            rawText,
            customApiKey: apiKey,
          }),
        });

        if (!token.isLive() || requestId !== parseRequest.current) return;
        if (res.ok && data.success && Array.isArray(data.questions)) {
          setParsedQuestions(data.questions);
          setParsedPassages(data.passages ?? []);
          setImportWarnings(data.warnings ?? []);
          setStatusMessage(`AI đã chuyển đổi thành công ${data.questions.length} câu hỏi có công thức KaTeX!`);
        } else {
          setErrorMessage(data.error || 'AI chưa đọc được tài liệu. Kết quả bên dưới chỉ là tách văn bản cơ bản, cần kiểm tra lại.');
          const fallback = parseRawVietnameseDocument(rawText);
          setParsedQuestions(fallback.questions);
          setParsedPassages(fallback.passages);
          setStatusMessage(`Bóc tách cơ bản ${fallback.questions.length} câu hỏi${fallback.passages.length ? ' và 1 ngữ liệu dùng chung' : ''} theo mẫu tiếng Việt.`);
        }
      }
    } catch (err: unknown) {
      if (token.isLive() && requestId === parseRequest.current) setErrorMessage(err instanceof Error ? err.message : 'Chưa đọc được tài liệu.');
    } finally {
      if (token.isLive() && requestId === parseRequest.current) setIsLoading(false);
      token.release();
    }
  };

  // Xóa bớt một câu hỏi khỏi danh sách xem trước
  const handleDeleteQuestion = (id: string) => {
    if (requestGate.current?.busy) return;
    setParsedQuestions(prev => prev.filter(q => q.id !== id));
  };

  // Thêm tất cả vào đề thi hiện tại
  const handleConfirmImport = async () => {
    if (accountLocked) return;
    if (!importGrade || !importSubject || !getCatalogSubjects(importGrade).some(s => s.key === importSubject)) {
      setErrorMessage('Hãy chọn môn và lớp của tài liệu trước khi đưa câu hỏi vào đề.'); return;
    }
    if (parsedQuestions.length > 0) {
      const gate = requestGate.current, token = gate?.begin();
      if (!gate || !token) return;
      setIsLoading(true);
      try {
      const response = await accountFetch(ownerId, '/api/auth/me', { signal: token.signal, cache: 'no-store' });
      const data = await response.json();
      if (!token.isLive()) return;
      if (!response.ok || data.user?.id !== ownerId) {
        gate.lock(); setAccountLocked(true); setIsLoading(false);
        setErrorMessage('Chưa xác nhận đúng tài khoản để nhập câu hỏi. Nguồn và bản xem trước được giữ; hãy tải lại trang bằng đúng tài khoản.'); return;
      }
      onImportQuestions(parsedQuestions.map(q => ({ ...q, id: `q_${crypto.randomUUID()}`, subject: importSubject, grade: importGrade, status: 'draft', verifiedBy: 'none' })), { subject: importSubject, grade: importGrade, passages: parsedPassages.filter(p => parsedQuestions.some(q => q.passageId === p.id)) });
      setParsedQuestions([]);
      handleClose();
      } catch (error) { if (token.isLive()) setErrorMessage(error instanceof Error ? error.message : 'Chưa xác nhận được tài khoản; bản xem trước vẫn giữ.'); }
      finally { if (token.isLive()) setIsLoading(false); token.release(); }
    }
  };

  return (
    <div className="fixed inset-0 z-50 bg-black/60 backdrop-blur-xs flex items-center justify-center p-3 sm:p-5">
