          </div>

          {/* CỘT PHẢI: KẾT QUẢ CÂU HỎI BÓC TÁCH */}
          <div className="flex flex-col h-full bg-[#f8f9fa] dark:bg-[#181818] border border-[#dadce0] dark:border-[#3c4043] rounded-2xl p-3.5 overflow-hidden">
