'use client';

import React, { useState, useRef, useEffect } from 'react';
import {
  Sparkles,
  Send,
  X,
  Bot,
  Brain,
  RefreshCw,
  HelpCircle,
  Lightbulb,
  FileText,
  CheckCircle2,
  ChevronRight
} from 'lucide-react';

interface ChatMessage {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  timestamp: string;
}

interface TeacherAiSecretaryDrawerProps {
  isOpen: boolean;
  onClose: () => void;
  currentUser: {
    name: string;
    email: string;
    role: string;
  };
  onOpenAiLearningModal: () => void;
}

export const TeacherAiSecretaryDrawer: React.FC<TeacherAiSecretaryDrawerProps> = ({
  isOpen,
  onClose,
  currentUser,
  onOpenAiLearningModal,
}) => {
  const [messages, setMessages] = useState<ChatMessage[]>(() => [
    {
      id: 'msg_welcome',
      role: 'assistant',
      content: `Kính chào Thầy/Cô ${currentUser.name}! Em là Thư ký số & Trợ lý sư phạm riêng của Thầy/Cô.\n\nEm đã được đồng bộ với kho đề thi và hồ sơ phong cách giảng dạy của Thầy/Cô. Thầy/Cô cần em hỗ trợ thống kê, tìm kiếm đề thi, hay tư vấn cấu trúc ra đề hôm nay ạ?`,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
    },
  ]);
  const [inputValue, setInputValue] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    if (isOpen) {
      scrollToBottom();
    }
  }, [messages, isOpen]);

  const quickPrompts = [
    '📊 Thống kê tình hình kho đề thi của tôi?',
    '💡 Tư vấn cấu trúc đề Tốt nghiệp THPT 2025 môn Toán?',
    '🎯 Gợi ý 3 bài toán thực tế Vận dụng cao?',
    '🔍 Có lưu ý pháp lý nào mới theo TT 17/2025 không?',
  ];

  const handleSendMessage = async (textToSend?: string) => {
    const text = (textToSend || inputValue).trim();
    if (!text || isLoading) return;

    const userMsg: ChatMessage = {
      id: `user_${crypto.randomUUID()}`,
      role: 'user',
      content: text,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
    };

    setMessages((prev) => [...prev, userMsg]);
    setInputValue('');
    setIsLoading(true);

    try {
      const historyPayload = messages.map((m) => ({
        role: m.role,
        content: m.content,
      }));

      const res = await fetch('/api/teacher/assistant', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          message: text,
          history: historyPayload,
        }),
      });

      const data = await res.json();
      if (data.success && data.reply) {
        const aiMsg: ChatMessage = {
          id: `ai_${crypto.randomUUID()}`,
          role: 'assistant',
          content: data.reply,
          timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        };
        setMessages((prev) => [...prev, aiMsg]);
      } else {
        const errorMsg: ChatMessage = {
          id: `ai_err_${crypto.randomUUID()}`,
          role: 'assistant',
          content: data.error || 'Dạ thưa Thầy/Cô, hiện tại em chưa kết nối được máy chủ AI. Thầy/Cô vui lòng kiểm tra lại Khóa AI cá nhân ạ.',
          timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        };
        setMessages((prev) => [...prev, errorMsg]);
      }
    } catch (err) {
      console.error(err);
      const errorMsg: ChatMessage = {
        id: `ai_err_${crypto.randomUUID()}`,
        role: 'assistant',
        content: 'Dạ, có lỗi kết nối mạng. Thầy/Cô vui lòng thử lại sau giây lát ạ.',
        timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      };
      setMessages((prev) => [...prev, errorMsg]);
    } finally {
      setIsLoading(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-y-0 right-0 z-50 w-full sm:w-[420px] bg-white dark:bg-[#1e1e1e] border-l border-[#dadce0] dark:border-[#3c4043] shadow-2xl flex flex-col animate-in slide-in-from-right duration-200">
      {/* Header */}
      <div className="h-16 px-4 border-b border-[#dadce0] dark:border-[#3c4043] flex items-center justify-between shrink-0 bg-white dark:bg-[#1e1e1e]">
        <div className="flex items-center gap-3">
          <div className="w-9 h-9 rounded-2xl bg-gradient-to-tr from-purple-600 to-indigo-600 text-white flex items-center justify-center shadow-xs">
            <Sparkles className="w-5 h-5 text-amber-300" />
          </div>
          <div>
            <div className="flex items-center gap-1.5">
              <h3 className="font-bold text-xs sm:text-sm text-[#202124] dark:text-white">
                Thư Ký Số & Trợ Lý Giáo Viên
              </h3>
              <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse" />
            </div>
            <p className="text-[11px] text-[#5f6368] dark:text-[#9aa0a6]">
              Trợ lý sư phạm cá nhân hóa
            </p>
          </div>
        </div>

        <div className="flex items-center gap-1">
          <button
            onClick={onOpenAiLearningModal}
            title="Xem hồ sơ phong cách mà em đã học từ Thầy/Cô"
            className="p-1.5 rounded-full text-purple-600 hover:bg-purple-50 dark:hover:bg-purple-950/40 transition-colors cursor-pointer"
          >
            <Brain className="w-4 h-4" />
          </button>
          <button
            onClick={onClose}
            className="p-1.5 rounded-full text-[#5f6368] hover:text-[#202124] dark:text-[#9aa0a6] dark:hover:text-white hover:bg-black/5 cursor-pointer transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>
      </div>

      {/* Profile Banner */}
      <div className="px-4 py-2 bg-purple-50/70 dark:bg-purple-950/30 border-b border-purple-100 dark:border-purple-900/40 flex items-center justify-between text-[11px] text-purple-900 dark:text-purple-200 shrink-0">
        <div className="flex items-center gap-1.5 truncate">
          <Brain className="w-3.5 h-3.5 text-purple-600 shrink-0" />
          <span className="truncate">Đang áp dụng Hồ sơ phong cách riêng của Thầy/Cô</span>
        </div>
        <button
          onClick={onOpenAiLearningModal}
          className="text-[10px] font-bold text-purple-700 dark:text-purple-300 hover:underline shrink-0 flex items-center"
        >
          <span>Xem</span>
          <ChevronRight className="w-3 h-3" />
        </button>
      </div>

      {/* Messages Scroll Area */}
      <div className="flex-1 overflow-y-auto p-4 space-y-3.5 min-h-0 bg-[#f8f9fa]/50 dark:bg-[#181818]/50">
        {messages.map((m) => (
          <div
            key={m.id}
            className={`flex flex-col ${
              m.role === 'user' ? 'items-end' : 'items-start'
            }`}
          >
            <div
              className={`max-w-[85%] rounded-2xl px-3.5 py-2.5 text-xs leading-relaxed shadow-2xs whitespace-pre-wrap ${
                m.role === 'user'
                  ? 'bg-[#1a73e8] text-white rounded-br-xs'
                  : 'bg-white dark:bg-[#252525] border border-[#dadce0] dark:border-[#3c4043] text-[#202124] dark:text-[#e3e3e3] rounded-bl-xs'
              }`}
            >
              {m.content}
            </div>
            <span className="text-[9px] text-[#5f6368] dark:text-[#9aa0a6] px-1 mt-1">
              {m.timestamp}
            </span>
          </div>
        ))}

        {isLoading && (
          <div className="flex items-center gap-2 text-xs text-[#5f6368] dark:text-[#9aa0a6] p-2 bg-white dark:bg-[#252525] rounded-xl border border-[#dadce0] dark:border-[#3c4043] w-fit shadow-2xs">
            <RefreshCw className="w-3.5 h-3.5 animate-spin text-purple-600" />
            <span>Thư ký AI đang soạn câu trả lời...</span>
          </div>
        )}

        <div ref={messagesEndRef} />
      </div>

      {/* Quick Prompts Suggestions */}
      <div className="p-2 border-t border-[#dadce0] dark:border-[#3c4043] bg-white dark:bg-[#1e1e1e] shrink-0">
        <div className="flex items-center gap-1.5 overflow-x-auto pb-1 no-scrollbar">
          {quickPrompts.map((q, idx) => (
            <button
              key={idx}
              disabled={isLoading}
              onClick={() => handleSendMessage(q.replace(/^[^\w\s]+\s*/, ''))}
              className="text-[11px] whitespace-nowrap px-2.5 py-1 rounded-full bg-[#f1f3f4] dark:bg-[#282828] hover:bg-[#e8f0fe] dark:hover:bg-[#1e2a38] text-[#3c4043] dark:text-[#e3e3e3] hover:text-[#1a73e8] transition-colors cursor-pointer shrink-0 border border-transparent hover:border-blue-200"
            >
              {q}
            </button>
          ))}
        </div>
      </div>

      {/* Input Area */}
      <div className="p-3 border-t border-[#dadce0] dark:border-[#3c4043] bg-white dark:bg-[#1e1e1e] shrink-0">
        <form
          onSubmit={(e) => {
            e.preventDefault();
            handleSendMessage();
          }}
          className="flex items-center gap-2 bg-[#f1f3f4] dark:bg-[#282828] rounded-2xl px-3 py-1.5 border border-transparent focus-within:border-[#1a73e8] focus-within:bg-white dark:focus-within:bg-[#1e1e1e] transition-colors"
        >
          <input
            type="text"
            placeholder="Hỏi Thư ký AI (thống kê kho đề, tư vấn cấu trúc, gợi ý câu hỏi)..."
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            disabled={isLoading}
            className="flex-1 bg-transparent text-xs text-[#202124] dark:text-white outline-hidden placeholder:text-[#5f6368] dark:placeholder:text-[#9aa0a6]"
          />
          <button
            type="submit"
            disabled={!inputValue.trim() || isLoading}
            className="w-7 h-7 rounded-full bg-[#1a73e8] hover:bg-[#1557b0] text-white flex items-center justify-center disabled:opacity-40 transition-all cursor-pointer shadow-2xs shrink-0"
          >
            <Send className="w-3.5 h-3.5" />
          </button>
        </form>
      </div>
    </div>
  );
};

'use client';

import React, { useState, useEffect, useRef } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import {
  Sparkles,
  Plus,
  Folder,
  FolderPlus,
  FolderOpen,
  FileText,
  Search,
  Star,
  Clock,
  Trash2,
  MoreVertical,
  Download,
  Edit3,
  Copy,
  LayoutGrid,
  List,
  ChevronRight,
  ChevronDown,
  Bot,
  GraduationCap,
  Users,
  Database,
  Upload,
  ArrowRight,
  Sun,
  Moon,
  Key,
  ShieldCheck,
  Check,
  X,
  AlertCircle,
  HelpCircle,
  Brain
} from 'lucide-react';
import { useTheme } from '@/components/ThemeProvider';
import { GenerateModal } from '@/components/GenerateModal';
import { ImportModal } from '@/components/ImportModal';
import { QuestionBankModal } from '@/components/QuestionBankModal';
import { ApiKeyModal } from '@/components/ApiKeyModal';
import { AiLearningModal } from '@/components/AiLearningModal';
import { TeacherAiSecretaryDrawer } from '@/components/TeacherAiSecretaryDrawer';
import { exportExamToDocx } from '@/lib/docx-export';
import { prepareExportFigures } from '@/lib/export-figures';
import { Exam } from '@/types/exam';
import { loadExam, persistExam } from '@/lib/exam-client';
import { writeDraft } from '@/lib/exam-draft';
import { accountFetch } from '@/lib/account-fetch';
import { LocalDraftsPanel } from '@/components/LocalDraftsPanel';
import { getCatalogSubjects } from '@/lib/education-catalog';

interface FolderData {
  id: string;
  name: string;
  color?: string;
  parentId?: string | null;
  _count?: { exams: number };
  children?: FolderData[];
}

interface ExamSummary {
  permissions?: Exam['access'];
  id: string;
  version: number;
  title: string;
  subject: string;
  grade: number;
  durationMinutes?: number | null;
  isStarred: boolean;
  folderId?: string | null;
  folder?: { id: string; name: string; color?: string } | null;
  updatedAt: string;
  createdAt: string;
  _count?: {
    items: number;
    assignments: number;
  };
}

interface TeacherDashboardProps {
  currentUser: {
    id: string;
    name: string;
    email: string;
    role: string;
  };
}

export const TeacherDashboard: React.FC<TeacherDashboardProps> = ({ currentUser }) => {
  const router = useRouter();
  const { theme, toggleTheme } = useTheme();

  // State dữ liệu
  const [folders, setFolders] = useState<FolderData[]>([]);
  const [exams, setExams] = useState<ExamSummary[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [page, setPageValue] = useState(1);
  const setPage = (value: React.SetStateAction<number>) => { setIsLoading(true); setPageValue(value); };
  const [totalPages, setTotalPages] = useState(1);
  const [totalExams, setTotalExams] = useState(0);
  const loadSequence = useRef(0);

  // Bộ lọc & Điều hướng
  const [currentView, setCurrentView] = useState<'all' | 'starred' | 'recent' | 'trash'>('all');
  const [selectedFolderId, setSelectedFolderId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedSubject, setSelectedSubject] = useState<string>('all');
  const [selectedGrade, setSelectedGrade] = useState<string>('all');
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');
  const [expandedFolders, setExpandedFolders] = useState<Record<string, boolean>>({});

  // Modals & Popups
  const [isGenerateModalOpen, setIsGenerateModalOpen] = useState(false);
  const [isImportModalOpen, setIsImportModalOpen] = useState(false);
  const [isQuestionBankOpen, setIsQuestionBankOpen] = useState(false);
  const [isApiKeyModalOpen, setIsApiKeyModalOpen] = useState(false);
  const [isAiSecretaryModalOpen, setIsAiSecretaryModalOpen] = useState(false);
  const [isAiLearningModalOpen, setIsAiLearningModalOpen] = useState(false);
  const [isCreateFolderModalOpen, setIsCreateFolderModalOpen] = useState(false);
  const [targetParentFolderId, setTargetParentFolderId] = useState<string | null>(null);
  const [folderNameInput, setFolderNameInput] = useState('');
  const [folderColorInput, setFolderColorInput] = useState('#1a73e8');

  // Thao tác với đề thi
  const [isRenameExamModalOpen, setIsRenameExamModalOpen] = useState(false);
  const [isMoveExamModalOpen, setIsMoveExamModalOpen] = useState(false);
  const [activeExam, setActiveExam] = useState<ExamSummary | null>(null);
  const [newExamTitle, setNewExamTitle] = useState('');
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  // Key stats
  const [hasActiveKey, setHasActiveKey] = useState(false);
  const [keyCount, setKeyCount] = useState(0);

  const showToast = (msg: string) => {
    setToastMessage(msg);
    setTimeout(() => setToastMessage(null), 3500);
  };

  // Nạp trạng thái Khóa AI
  const loadKeyStatus = () => accountFetch(currentUser.id, '/api/user/keys').then(async res => {
    if (res.ok) {
      const data = await res.json(); const activeKeys = (data.keys || []).filter((key: { isActive: boolean }) => key.isActive);
      setHasActiveKey(activeKeys.length > 0); setKeyCount(activeKeys.length);
    }
  }).catch(() => { /* Keep the last acknowledged state if offline. */ });
  const loadFolders = () => accountFetch(currentUser.id, '/api/folders').then(async res => {
    if (res.ok) { const data = await res.json(); setFolders(data.folders || []); }
  }).catch(error => { console.error('Lỗi nạp thư mục:', error); });

  // Nạp danh sách Đề thi theo bộ lọc
  const readExams = () => {
    const sequence = ++loadSequence.current;
      const params = new URLSearchParams();
      params.set('page', String(page)); params.set('limit', '20');
      if (searchQuery) params.append('search', searchQuery);
      if (selectedSubject !== 'all') params.append('subject', selectedSubject);
      if (selectedGrade !== 'all') params.append('grade', selectedGrade);

      if (currentView === 'trash') {
        params.append('isTrash', 'true');
      } else {
        if (currentView === 'starred') {
          params.append('isStarred', 'true');
        }
        if (selectedFolderId) {
          params.append('folderId', selectedFolderId);
        }
      }

      return accountFetch(currentUser.id, `/api/exams?${params.toString()}`).then(async res => {
      if (res.ok) {
        const data = await res.json();
        if (sequence !== loadSequence.current) return;
        setExams(data.exams || []);
        setTotalPages(Math.max(1, data.pagination?.totalPages ?? 1));
        setTotalExams(data.pagination?.totalCount ?? 0);
        if (page > Math.max(1, data.pagination?.totalPages ?? 1)) setPage(Math.max(1, data.pagination?.totalPages ?? 1));
      } else {
        const data = await res.json();
        if (sequence === loadSequence.current) showToast(data.error || 'Chưa tải được kho đề.');
      }
      }).catch(error => { console.error('Lỗi nạp danh sách đề thi:', error); }).finally(() => {
        if (sequence === loadSequence.current) setIsLoading(false);
      });
  };
  const loadExams = () => { setIsLoading(true); return readExams(); };

  useEffect(() => {
    loadKeyStatus();
    loadFolders();
  }, []);

  const filters = JSON.stringify([currentUser.id, currentView, selectedFolderId, selectedSubject, selectedGrade, searchQuery]);
  const [previousFilters, setPreviousFilters] = useState(filters);
  if (previousFilters !== filters) { setPreviousFilters(filters); setPage(1); }

  useEffect(() => {
    void readExams();
  }, [currentView, selectedFolderId, selectedSubject, selectedGrade, searchQuery, page]);

  // Tạo thư mục mới
  const handleCreateFolder = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!folderNameInput.trim()) return;

    try {
      const res = await accountFetch(currentUser.id, '/api/folders', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: folderNameInput.trim(),
          color: folderColorInput,
          parentId: targetParentFolderId,
        }),
      });

      const data = await res.json();
      if (res.ok) {
        showToast('Đã tạo thư mục mới thành công!');
        setIsCreateFolderModalOpen(false);
        setFolderNameInput('');
        setTargetParentFolderId(null);
        loadFolders();
      } else {
        alert(data.error || 'Không thể tạo thư mục');
      }
    } catch {
      alert('Lỗi kết nối máy chủ khi tạo thư mục');
    }
  };

  // Xóa thư mục
  const handleDeleteFolder = async (folderId: string, folderName: string) => {
    if (!confirm(`Thầy/Cô có chắc chắn muốn xóa thư mục "${folderName}"? Các đề thi bên trong sẽ được chuyển ra ngoài an toàn.`)) {
      return;
    }

    try {
      const res = await accountFetch(currentUser.id, `/api/folders/${folderId}`, { method: 'DELETE' });
      if (res.ok) {
        showToast('Đã xóa thư mục.');
        if (selectedFolderId === folderId) setSelectedFolderId(null);
        loadFolders();
        loadExams();
      }
    } catch {
      alert('Lỗi khi xóa thư mục');
    }
  };

  // Đổi trạng thái Gắn sao (Starred)
  const handleToggleStar = async (exam: ExamSummary, e: React.MouseEvent) => {
    e.stopPropagation();
    try {
      const res = await accountFetch(currentUser.id, `/api/exams/${exam.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ isStarred: !exam.isStarred, baseVersion: exam.version }),
      });
      if (!res.ok) { const result = await res.json(); showToast(result.error || 'Thao tác chưa được lưu'); await loadExams(); return; }
      if (res.ok) {
        await loadExams();
      }
    } catch {
      // ignore
    }
  };

  // Đổi tên đề thi
  const handleRenameExam = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!activeExam || !newExamTitle.trim()) return;

    try {
      const res = await accountFetch(currentUser.id, `/api/exams/${activeExam.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title: newExamTitle.trim(), baseVersion: activeExam.version }),
      });
      if (!res.ok) { const result = await res.json(); showToast(result.error || 'Thao tác chưa được lưu'); await loadExams(); return; }
      if (res.ok) {
        showToast('Đã đổi tên đề thi thành công!');
        setIsRenameExamModalOpen(false);
        await loadExams();
      }
    } catch {
      alert('Lỗi khi đổi tên đề thi');
    }
  };

  // Di chuyển đề thi vào thư mục
  const handleMoveExam = async (targetFolderId: string | null) => {
    if (!activeExam) return;

    try {
      const res = await accountFetch(currentUser.id, `/api/exams/${activeExam.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ folderId: targetFolderId, baseVersion: activeExam.version }),
      });
      if (!res.ok) { const result = await res.json(); showToast(result.error || 'Thao tác chưa được lưu'); await loadExams(); return; }
      if (res.ok) {
        showToast('Đã di chuyển đề thi vào thư mục mới!');
        setIsMoveExamModalOpen(false);
        loadExams();
        loadFolders();
      }
    } catch {
      alert('Lỗi khi di chuyển đề thi');
    }
  };

  // Xóa đề thi vào thùng rác
  const handleDeleteExam = async (examId: string, e?: React.MouseEvent) => {
    if (e) e.stopPropagation();
    if (currentView === 'trash') {
      const item = exams.find(exam => exam.id === examId);
      const response = await accountFetch(currentUser.id, '/api/exams/' + examId, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ restore: true, baseVersion: item?.version }) });
      const result = await response.json();
      if (!response.ok) { showToast(result.error || 'Chưa khôi phục được đề'); return; }
      showToast('Đã khôi phục đề'); await loadExams(); return;
    }
    if (!confirm('Chuyển đề này vào thùng rác? Bạn có thể khôi phục sau.')) return;

    try {
      const res = await accountFetch(currentUser.id, `/api/exams/${examId}`, { method: 'DELETE', headers: { 'If-Match': String(exams.find(item => item.id === examId)?.version ?? '') } });
      if (!res.ok) { const result = await res.json(); showToast(result.error || 'Chưa chuyển được đề vào thùng rác'); await loadExams(); return; }
      if (res.ok) {
        showToast('Đã chuyển đề thi vào Thùng rác.');
        loadExams();
        loadFolders();
      }
    } catch {
      alert('Lỗi khi xóa đề thi');
    }
  };

  // Nhân bản đề thi (Clone)
  const handleCloneExam = async (exam: ExamSummary, e?: React.MouseEvent) => {
    if (e) e.stopPropagation();
    try {
      const original = await loadExam(exam.id, currentUser.id);
      await persistExam({ ...original, id: 'draft_' + crypto.randomUUID(), serverId: undefined, version: undefined, metadata: { ...original.metadata, title: original.metadata.title + ' (Bản sao)' } }, currentUser.id);
      const resCreate = { ok: true };

      if (resCreate.ok) {
        showToast('Đã nhân bản đề thi thành công!');
        loadExams();
        loadFolders();
      }
    } catch {
      alert('Lỗi khi nhân bản đề thi');
    }
  };

  // Mở soạn thảo đề thi
  const handleOpenEditor = (examId?: string) => {
    if (examId) {
      router.push(`/editor/${examId}`);
    } else {
      router.push('/editor/new');
    }
  };

  // Khi AI sinh đề thành công từ Dashboard
  const handleExamGeneratedFromAi = async (generatedExam: Exam) => {
    // Keep the preview open if preserving the draft fails.
    writeDraft(localStorage, currentUser.id, 'new', { ...generatedExam, id: 'draft_' + crypto.randomUUID(), serverId: undefined, version: undefined });
    setIsGenerateModalOpen(false);
    showToast('Đã giữ bản nháp. Đang mở bàn soạn...');
    router.push('/editor/new');
  };

  // Xuất file Word nhanh từ danh sách
  const handleQuickExportDocx = async (examSummary: ExamSummary, e: React.MouseEvent) => {
    e.stopPropagation();
    try {
      showToast('Đang chuẩn bị file Word...');
      const fullExamObj = await loadExam(examSummary.id, currentUser.id);

      const blob = await exportExamToDocx(await prepareExportFigures(fullExamObj), true);
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `${examSummary.title.replace(/\s+/g, '_')}.docx`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
      showToast('Tải file Word thành công!');
    } catch (err) {
      console.error(err);
      alert(err instanceof Error ? err.message : 'Lỗi khi xuất file Word');
    }
  };

  const currentFolder = folders.find(f => f.id === selectedFolderId) ||
    folders.flatMap(f => f.children || []).find(c => c.id === selectedFolderId);

  return (
    <div className="flex flex-col h-screen w-screen bg-[#F8F9FA] dark:bg-[#181818] text-[#202124] dark:text-[#E3E3E3] font-sans antialiased overflow-hidden select-none">
      {/* ─────────────────────────────────────────────────────────────
          1. HEADER TRÊN CÙNG (Google App Bar Style)
      ───────────────────────────────────────────────────────────── */}
      <header className="h-16 px-4 sm:px-6 bg-white dark:bg-[#1e1e1e] border-b border-[#dadce0] dark:border-[#3c4043] flex items-center justify-between z-30 shrink-0 shadow-2xs">
        {/* Góc trái: Logo & Định danh thương hiệu */}
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-2xl bg-gradient-to-tr from-[#1a73e8] to-[#4285f4] flex items-center justify-center text-white shadow-xs">
            <GraduationCap className="w-6 h-6" />
          </div>
          <div>
            <div className="flex items-center gap-2">
              <span className="font-extrabold text-base tracking-tight text-[#202124] dark:text-white">ExamCraft</span>
              <span className="text-[10px] font-bold px-1.5 py-0.5 rounded-full bg-[#e8f0fe] dark:bg-[#1e2a38] text-[#1a73e8] dark:text-[#8ab4f8]">
                Kho Đề Cá Nhân
              </span>
            </div>
            <p className="text-[11px] text-[#5f6368] dark:text-[#9aa0a6] hidden sm:block">
              Soạn đề, quản lý câu hỏi và giao bài
            </p>
          </div>
        </div>

        {/* Giữa: Ô tìm kiếm thông minh */}
        <div className="flex-1 max-w-xl mx-4 lg:mx-8 hidden md:block">
          <div className="relative">
            <Search className="w-4 h-4 text-[#5f6368] dark:text-[#9aa0a6] absolute left-3.5 top-1/2 -translate-y-1/2" />
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Tìm kiếm theo tên đề, mã môn, năm học..."
              className="w-full pl-10 pr-9 py-2 bg-[#f1f3f4] dark:bg-[#282828] border border-transparent focus:border-[#1a73e8] focus:bg-white dark:focus:bg-[#1e1e1e] rounded-full text-xs text-[#202124] dark:text-[#e3e3e3] outline-hidden transition-all shadow-2xs"
            />
            {searchQuery && (
              <button
                onClick={() => setSearchQuery('')}
