/**
 * Xóa bỏ ký hiệu LaTeX thô hoặc làm sạch chuẩn xác để hiển thị trong Word
 * Xử lý từ khóa dài trước, từ khóa ngắn sau kèm lookahead/boundary để không cắn xé từ vựng.
 */
export function cleanLatexForWord(text: string): string {
  if (!text) return '';
  let result = text;

  // 1. Gỡ bỏ ký hiệu bao khối toán $$ và $
  result = result.replace(/\$\$/g, '').replace(/\$/g, '');

  // 2. Xử lý các macro dài trước để tránh bị token ngắn cắn xé
  result = result
    .replace(/\\infty/g, '∞')
    .replace(/\\int_\{([^}]+)\}\^\{([^}]+)\}/g, '∫($1→$2)')
    .replace(/\\int_([^\s^]+)\^([^\s]+)/g, '∫($1→$2)')
    .replace(/\\int/g, '∫')
    .replace(/\\lim_\{([^}]+)\}/g, 'lim($1)')
    .replace(/\\left\s*/g, '')
    .replace(/\\right\s*/g, '')
    .replace(/\\leq/g, '≤')
    .replace(/\\geq/g, '≥')
    .replace(/\\neq/g, '≠')
    .replace(/\\approx/g, '≈')
    .replace(/\\times/g, '×')
    .replace(/\\div/g, '÷')
    .replace(/\\pm/g, '±')
    .replace(/\\to/g, '→')
    .replace(/\\alpha/g, 'α')
    .replace(/\\beta/g, 'β')
    .replace(/\\gamma/g, 'γ')
    .replace(/\\lambda/g, 'λ')
    .replace(/\\omega/g, 'ω')
    .replace(/\\Omega/g, 'Ω')
    .replace(/\\mu/g, 'μ')
    .replace(/\\rho/g, 'ρ')
    .replace(/\\theta/g, 'θ')
    .replace(/\\varphi/g, 'φ')
    .replace(/\\phi/g, 'ϕ')
    .replace(/\\sigma/g, 'σ')
    .replace(/\\tau/g, 'τ')
    .replace(/\\pi/g, 'π')
    .replace(/\\Delta/g, 'Δ')
    .replace(/\^\\circ/g, '°')
    .replace(/\\circ/g, '°')
    .replace(/\\widehat\{([^}]+)\}/g, '∠$1')
    .replace(/\\vec\{([^}]+)\}/g, '$1⃗')
    .replace(/\\ce\{([^{}]+)\}/g, (_m, p1) => {
      return p1
        .replace(/\s*->\s*/g, ' → ')
        .replace(/\s*<=>\s*/g, ' ⇌ ')
        .replace(/\^/g, '↑')
        .replace(/v/g, '↓');
    })
    // Xử lý ký hiệu hạt nhân nguyên tử: _{Z}^{A}X -> (A/Z)X
    .replace(/_\{([^{}]+)\}\^\{([^{}]+)\}(?:\\text\{)?([a-zA-Z]+)\}?/g, '($2/$1)$3')
    .replace(/\\mathbb\{R\}/g, 'ℝ')
    .replace(/\\mathbb\{Z\}/g, 'ℤ')
    .replace(/\\mathbb\{Q\}/g, 'ℚ')
    .replace(/\\mathbb\{N\}/g, 'ℕ')
    .replace(/\\setminus/g, ' \\ ')
    .replace(/\\cup/g, ' ∪ ')
    .replace(/\\cap/g, ' ∩ ')
    .replace(/\\mathrm\{e\}/g, 'e')
    .replace(/\\mathrm\{([^}]+)\}/g, '$1')
    .replace(/\\text\{([^}]+)\}/g, '$1')
    .replace(/\\mathbf\{([^}]+)\}/g, '$1');

  // 3. Xử lý các token ngắn với ranh giới từ hoặc lookahead
  result = result
    .replace(/\\le(?![a-zA-Z])/g, '≤')
    .replace(/\\ge(?![a-zA-Z])/g, '≥')
    .replace(/\\ne(?![a-zA-Z])/g, '≠')
    .replace(/\\in(?![a-zA-Z])/g, '∈');

  // 4. Xử lý lặp để gỡ sạch ngoặc lồng nhau của \frac, \dfrac, \sqrt
  let prev = '';
  while (prev !== result && (result.includes('\\frac') || result.includes('\\dfrac') || result.includes('\\sqrt'))) {
    prev = result;
    result = result.replace(/\\sqrt\[([^{}]+)\]\{([^{}]+)\}/g, '√[$1]($2)');
    result = result.replace(/\\sqrt\{([^{}]+)\}/g, '√($1)');
    result = result.replace(/\\(?:d?frac)\{([^{}]+)\}\{([^{}]+)\}/g, '($1 / $2)');
  }

  // 5. Xử lý ma trận (matrix, pmatrix, bmatrix, vmatrix)
  result = result
    .replace(/\\begin\{(?:p|b)?matrix\}/g, '[ ')
    .replace(/\\end\{(?:p|b)?matrix\}/g, ' ]')
    .replace(/\\begin\{vmatrix\}/g, '| ')
    .replace(/\\end\{vmatrix\}/g, ' |')
    .replace(/\\begin\{cases\}/g, '{ ')
    .replace(/\\end\{cases\}/g, ' }')
    .replace(/\\\\/g, '; ')
    .replace(/&/g, '  ');

  // 6. Xử lý bảng biến thiên
  result = result.replace(/\[BANG_BIEN_THIEN[^\]]*\]/g, '[Bảng biến thiên đính kèm]');

  // 7. Dọn dẹp khoảng trắng thừa và dấu gạch chéo
  result = result
    .replace(/\\,/g, ' ')
    .replace(/\\;/g, ' ')
    .replace(/\\!/g, '')
    .replace(/\\quad/g, '    ');

  return result.trim();
}

/**
 * Tách một chuỗi văn bản có lẫn công thức $...$ hoặc $$...$$ thành mảng các TextRun và Math element của docx (OMML)
 */
export function renderLatexRunsForWord(
  rawText: string,
  options?: { fontSize?: number; font?: string; bold?: boolean; italics?: boolean }
): (TextRun | Math)[] {
  if (!rawText) return [];
  const runs: (TextRun | Math)[] = [];
  const fontSize = options?.fontSize || 22;
  const font = options?.font || 'Times New Roman';

  // Biểu thức tách chuỗi: tìm các đoạn $$...$$ hoặc $...$
  const regex = /(\$\$[\s\S]*?\$\$|\$[^$]+\$)/g;
  let lastIndex = 0;
  let match: RegExpExecArray | null;

  while ((match = regex.exec(rawText)) !== null) {
    const textBefore = rawText.slice(lastIndex, match.index);
    if (textBefore) {
      runs.push(
        new TextRun({
          text: textBefore,
          font,
          size: fontSize,
          bold: options?.bold,
          italics: options?.italics,
        })
      );
    }

    const mathExpr = match[0];
    const innerMath = mathExpr.replace(/^\$\$|\$\$$/g, '').replace(/^\$|\$$/g, '').trim();

    // Phân tích biểu thức LaTeX thành phương trình Word thật: phân số, căn, chỉ số trên/dưới, tổng, giới hạn
    runs.push(new Math({ children: latexToMath(innerMath) }));

    lastIndex = regex.lastIndex;
  }

  // Đoạn văn bản còn lại sau cùng
  const remainingText = rawText.slice(lastIndex);
  if (remainingText) {
    runs.push(
      new TextRun({
        text: remainingText,
        font,
        size: fontSize,
        bold: options?.bold,
        italics: options?.italics,
      })
    );
  }

  // Nếu chuỗi không chứa ký hiệu $ nào, fallback đơn giản
  if (runs.length === 0 && rawText) {
    runs.push(
      new TextRun({
        text: cleanLatexForWord(rawText),
        font,
        size: fontSize,
        bold: options?.bold,
        italics: options?.italics,
      })
    );
  }

  return runs;
}

/**
 * Chuyển đổi và render hình vẽ, đồ thị hàm số và bảng biến thiên vào file Word docx (EXP-BUG-001)
 */
export function renderFiguresForDocx(figures?: Figure[], compact = false): (Paragraph | Table)[] {
  if (!figures || figures.length === 0) return [];
  const elements: (Paragraph | Table)[] = [];

  for (const fig of figures) {
    if (fig.renderedBase64) {
      try {
        const cleanBase64 = fig.renderedBase64.replace(/^data:image\/\w+;base64,/, '');
        const imgBuffer = Buffer.from(cleanBase64, 'base64');
        const dimensions = (fig as Figure & { exportSize?: { width: number; height: number } }).exportSize;
        const width = dimensions?.width ?? 380, height = dimensions?.height ?? 240;
        const scale = compact ? globalThis.Math.min(1, 230 / width) : 1;
        elements.push(
          new Paragraph({
            alignment: AlignmentType.CENTER,
            spacing: { before: 100, after: 60 },
            children: [
              new ImageRun({
                data: imgBuffer,
                transformation: {
                  width: width * scale,
                  height: height * scale,
                },
                type: fig.renderedBase64.startsWith('data:image/jpeg') ? 'jpg' : fig.renderedBase64.startsWith('data:image/gif') ? 'gif' : 'png',
              }),
            ],
          })
        );
      } catch {
        throw new Error(`Không chèn được hình “${fig.caption ?? fig.id}” vào Word. Dữ liệu gốc vẫn được giữ.`);
      }
    } else if (fig.kind === 'variation_table' && fig.data) {
      const vData = fig.data as VariationTableData;
      if (!Array.isArray(vData.xValues) || vData.xValues.length < 2 || !Array.isArray(vData.yPrimeSigns) || !vData.yPrimeSigns.length || !Array.isArray(vData.yValues) || !vData.yValues.length) throw new Error(`Bảng biến thiên “${fig.caption ?? fig.id}” chưa đủ dữ liệu.`);
      if (Array.isArray(vData.xValues) && Array.isArray(vData.yPrimeSigns)) {
        // Tạo bảng biến thiên dạng Table trong docx
        const totalWidth = compact ? 3450 : 8500; // dxa
        const headerColWidth = 1000;
        const contentColWidth = globalThis.Math.floor((totalWidth - headerColWidth) / globalThis.Math.max(1, vData.xValues.length));

        // Hàng 1: x
        const rowXCells = [
          new TableCell({
            width: { size: headerColWidth, type: WidthType.DXA },
            children: [
              new Paragraph({
                alignment: AlignmentType.CENTER,
                children: [new TextRun({ text: 'x', bold: true, italics: true, font: 'Times New Roman', size: 20 })],
              }),
            ],
          }),
          ...vData.xValues.map((xVal: string) =>
            new TableCell({
              width: { size: contentColWidth, type: WidthType.DXA },
              children: [
                new Paragraph({
                  alignment: AlignmentType.CENTER,
                  children: [new TextRun({ text: cleanLatexForWord(xVal), font: 'Times New Roman', size: 20 })],
                }),
              ],
            })
          ),
        ];

        // Hàng 2: y'
        const rowYPrimeCells = [
          new TableCell({
            width: { size: headerColWidth, type: WidthType.DXA },
            children: [
              new Paragraph({
                alignment: AlignmentType.CENTER,
                children: [new TextRun({ text: "y'", bold: true, italics: true, font: 'Times New Roman', size: 20 })],
              }),
            ],
          }),
          new TableCell({
            columnSpan: vData.xValues.length,
            children: [
              new Paragraph({
                alignment: AlignmentType.CENTER,
                children: [
                  new TextRun({
                    text: vData.yPrimeSigns.map((s: string) => `  ${s}  `).join(''),
                    bold: true,
                    font: 'Times New Roman',
                    size: 20,
                  }),
                ],
              }),
            ],
          }),
        ];

        // Hàng 3: y
        let ySummary = '';
        if (Array.isArray(vData.yValues)) {
          ySummary = vData.yValues
            .map((yv) => {
              if (yv.type === 'up') return ' ↗ ';
              if (yv.type === 'down') return ' ↘ ';
              return cleanLatexForWord(yv.val || '');
            })
            .join(' ');
        }
        const rowYCells = [
          new TableCell({
            width: { size: headerColWidth, type: WidthType.DXA },
            children: [
              new Paragraph({
                alignment: AlignmentType.CENTER,
                children: [new TextRun({ text: 'y', bold: true, italics: true, font: 'Times New Roman', size: 20 })],
              }),
            ],
          }),
          new TableCell({
            columnSpan: vData.xValues.length,
            children: [
              new Paragraph({
                alignment: AlignmentType.CENTER,
                children: [new TextRun({ text: ySummary || 'Giá trị hàm số biến thiên', font: 'Times New Roman', size: 20 })],
              }),
            ],
          }),
        ];

        const varTable = new Table({
          width: { size: totalWidth, type: WidthType.DXA },
          alignment: AlignmentType.CENTER,
          borders: {
            top: { style: BorderStyle.SINGLE, size: 6, color: '666666' },
            bottom: { style: BorderStyle.SINGLE, size: 6, color: '666666' },
            left: { style: BorderStyle.SINGLE, size: 6, color: '666666' },
            right: { style: BorderStyle.SINGLE, size: 6, color: '666666' },
            insideHorizontal: { style: BorderStyle.SINGLE, size: 4, color: '888888' },
            insideVertical: { style: BorderStyle.SINGLE, size: 4, color: 'CCCCCC' },
          },
          rows: [
            new TableRow({ children: rowXCells }),
            new TableRow({ children: rowYPrimeCells }),
            new TableRow({ children: rowYCells }),
          ],
        });
        elements.push(varTable);
      }
    } else {
      throw new Error(`Hình “${fig.caption ?? fig.id}” chưa có ảnh để xuất Word. Hãy xuất từ bàn soạn sau khi kiểm tra hình.`);
    }

    if (fig.caption) {
      elements.push(
        new Paragraph({
          alignment: AlignmentType.CENTER,
          spacing: { before: 40, after: 80 },
          children: [
            new TextRun({
              text: fig.caption,
              italics: true,
              size: 20,
              font: 'Times New Roman',
            }),
          ],
        })
      );
    }
  }

  return elements;
}

/**
 * Tạo tài liệu Word .docx hoàn chỉnh theo quy chuẩn đề thi Việt Nam
 */
export async function exportExamToDocx(
  exam: Exam, 
  includeSolutions: boolean = true, 
  includeMatrix: boolean = true,
  view: 'all' | 'exam' | 'answers' | 'solutions' | 'matrix' | 'parallel' = 'all'
): Promise<Blob> {
  const { metadata, questions } = exam;

  const headerLines = resolveHeaderLines(exam);
  const headerParagraph = (line: ReturnType<typeof resolveHeaderLines>[number]) => new Paragraph({
    alignment: line.align === 'left' ? AlignmentType.LEFT : line.align === 'right' ? AlignmentType.RIGHT : AlignmentType.CENTER,
    children: [new TextRun({ text: line.text, bold: line.bold, italics: line.italic, font: 'Times New Roman', size: 22 })],
  });
  const headerAreas = ['left', 'right'].filter(area => headerLines.some(line => line.area === area));
  const headerBlocks: (Paragraph | Table)[] = headerAreas.length ? [new Table({
    width: { size: 100, type: WidthType.PERCENTAGE },
    borders: { top: { style: BorderStyle.NONE }, bottom: { style: BorderStyle.NONE }, left: { style: BorderStyle.NONE }, right: { style: BorderStyle.NONE }, insideHorizontal: { style: BorderStyle.NONE }, insideVertical: { style: BorderStyle.NONE } },
    rows: [new TableRow({ children: headerAreas.map(area => new TableCell({ width: { size: 100 / headerAreas.length, type: WidthType.PERCENTAGE }, children: headerLines.filter(line => line.area === area).map(headerParagraph) })) })],
  })] : [];

  // Thông tin học sinh & số báo danh
  const studentInfoTable = new Table({
    width: { size: 100, type: WidthType.PERCENTAGE },
    borders: {
      top: { style: BorderStyle.SINGLE, size: 4, color: 'D1D5DB' },
      bottom: { style: BorderStyle.SINGLE, size: 4, color: 'D1D5DB' },
      left: { style: BorderStyle.NONE },
      right: { style: BorderStyle.NONE },
      insideHorizontal: { style: BorderStyle.NONE },
      insideVertical: { style: BorderStyle.NONE },
    },
    rows: [
      new TableRow({
        children: [
          new TableCell({
            width: { size: 65, type: WidthType.PERCENTAGE },
            children: [
              new Paragraph({
                spacing: { before: 80, after: 80 },
                children: [
                  new TextRun({
                    text: 'Họ và tên thí sinh: ............................................................................',
                    font: 'Times New Roman',
                    size: 20,
                  }),
                ],
              }),
            ],
          }),
          new TableCell({
            width: { size: 35, type: WidthType.PERCENTAGE },
            children: [
              new Paragraph({
                spacing: { before: 80, after: 80 },
                children: [
                  new TextRun({
                    text: 'Số báo danh: .............................',
                    font: 'Times New Roman',
                    size: 20,
                  }),
                ],
              }),
            ],
          }),
        ],
      }),
    ],
  });

  const docChildren: (Paragraph | Table)[] = [];
  const parallelQuestions: (Paragraph | Table)[][] = [], parallelAnswers: (Paragraph | Table)[][] = [];

  // Nếu bật tùy chọn Ma trận: Chèn bảng Ma trận CV 7991 lên trang đầu
  if (includeMatrix) {
    const plan = examPlanOutput(exam);
    if (plan) {
      const text = (value: string, bold = false) => new Paragraph({ spacing: { before: 60, after: 60 }, children: [new TextRun({ text: value, bold, font: 'Times New Roman', size: 19 })] });
      docChildren.push(text(plan.title, true), text(plan.disclaimer), text(plan.status, true), ...plan.summaries.map(value => text(value)));
      if (plan.headers.length) {
        const row = (cells: string[], header = false) => new TableRow({ tableHeader: header, children: cells.map(value => new TableCell({ width: { size: 25, type: WidthType.PERCENTAGE }, children: [text(value, header)] })) });
        docChildren.push(new Table({ width: { size: 100, type: WidthType.PERCENTAGE }, rows: [row(plan.headers, true), ...plan.rows.map(cells => row(cells))] }));
      }
      if (plan.warnings.length) docChildren.push(text('Cần rà soát', true), ...plan.warnings.map(value => text(value)));
    }
    docChildren.push(
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { before: 100, after: 140 },
        children: [
          new TextRun({
            text: 'BẢNG PHÂN BỔ CÂU HỎI — THEO KHUNG ĐÃ CHỌN',
            bold: true,
            size: 24,
            font: 'Times New Roman',
          }),
        ],
      }),
      generateDocxMatrixTable(computeExamMatrix(exam)),
      new Paragraph({
        spacing: { before: 140, after: 100 },
        children: [new PageBreak()],
      })
    );
  }

  const questionBodyStart = docChildren.length;
  docChildren.push(
    ...headerBlocks,
    new Paragraph({ spacing: { before: 100, after: 100 } }),
    studentInfoTable,
    new Paragraph({ spacing: { before: 150, after: 100 } }),
  );

  const passageStart = docChildren.length;
  // In các ngữ liệu chung (Passages) nếu có
  if (exam.passages && exam.passages.length > 0) {
    for (const p of exam.passages) {
      docChildren.push(
        new Paragraph({
          spacing: { before: 200, after: 80 },
          children: [
            new TextRun({
              text: p.title ? `NGỮ LIỆU: ${p.title}` : 'ĐỌC NGỮ LIỆU SAU ĐÂY:',
              bold: true,
              size: 22,
              font: 'Times New Roman',
            }),
          ],
        }),
        new Paragraph({
          indent: { left: 300, right: 300 },
          spacing: { after: 160 },
          children: renderLatexRunsForWord(p.content, { fontSize: 20, italics: true }),
        })
      );
      docChildren.push(...renderFiguresForDocx(p.figures));
      if (p.source) docChildren.push(new Paragraph({ children: [new TextRun({ text: p.source, italics: true, size: 20 })] }));
    }
  }

  const passageBlocks = docChildren.slice(passageStart);
  // Follow the editor's ordering so answer numbers and shared passages remain linked.
  const sections = (exam as Exam & { sections?: { id: string; title?: string; label?: string; name?: string }[] }).sections ?? [];
  let previousSection: string | undefined;
  questions.forEach((q, index) => {
    const blockStart = docChildren.length;
    if (q.sectionId && q.sectionId !== previousSection) {
      const section = sections.find(section => section.id === q.sectionId);
      if (section?.title || section?.label || section?.name) docChildren.push(new Paragraph({ children: [new TextRun({ text: section.title ?? section.label ?? section.name!, bold: true, size: 23 })], spacing: { before: 200, after: 100 } }));
      previousSection = q.sectionId;
    }
    docChildren.push(new Paragraph({ spacing: { before: 140, after: 80 }, children: [new TextRun({ text: 'Câu ' + (index + 1) + ': ', bold: true, size: 22 }), ...renderLatexRunsForWord(q.content, { fontSize: 22 })] }));
    if (q.passageId) {
      const passage = exam.passages?.find(p => p.id === q.passageId);
      docChildren.push(new Paragraph({ children: [new TextRun({ text: passage ? 'Theo ngữ liệu: ' + (passage.title ?? passage.id) : '[Thiếu ngữ liệu liên kết: ' + q.passageId + ']', italics: true, size: 20 })] }));
    }
    if (q.type === 'multiple_choice') q.choices?.forEach(choice => docChildren.push(new Paragraph({ indent: { left: 300 }, children: [new TextRun({ text: choice.key + '. ', bold: true, size: 22 }), ...renderLatexRunsForWord(choice.text, { fontSize: 22 })] })));
    if (q.type === 'true_false_group') q.sub_questions?.forEach(sub => docChildren.push(new Paragraph({ indent: { left: 300 }, children: [new TextRun({ text: sub.key + ') ', bold: true, size: 22 }), ...renderLatexRunsForWord(sub.content, { fontSize: 22 }), new TextRun({ text: '    □ Đúng    □ Sai', size: 20 })] })));
    if (q.type === 'matching') {
      const matching = matchingDisplay(q);
      if (matching) {
        const row = (left: string, right: string) => new TableRow({ children: [left, right].map(text => new TableCell({ width: { size: 50, type: WidthType.PERCENTAGE }, children: [new Paragraph({ children: renderLatexRunsForWord(text, { fontSize: 22 }) })] })) });
        docChildren.push(new Table({ width: { size: 100, type: WidthType.PERCENTAGE }, rows: [row('Cột trái', 'Cột phải'), ...Array.from({ length: globalThis.Math.max(matching.left.length, matching.right.length) }, (_, i) => row(matching.left[i] ? (i + 1) + '. ' + matching.left[i].text : '', matching.right[i] ? String.fromCharCode(65 + i) + '. ' + matching.right[i].text : ''))] }));
      } else docChildren.push(new Paragraph('[Chưa thiết lập hai cột ghép nối]'));
    }
    if (q.type === 'ordering') {
      const ordering = orderingDisplay(q);
      if (ordering) ordering.items.forEach((item, i) => docChildren.push(new Paragraph({ children: [new TextRun({ text: '[' + (i + 1) + '] ', bold: true }), ...renderLatexRunsForWord(item.text, { fontSize: 22 })] })));
      else docChildren.push(new Paragraph('[Chưa thiết lập các mục sắp xếp]'));
    }
    if (['short_answer', 'fill_blank', 'ordering', 'matching'].includes(q.type)) docChildren.push(new Paragraph('Trả lời: ................................................................................'));
    docChildren.push(...renderFiguresForDocx(q.figures, view === 'parallel'));
    parallelQuestions.push(docChildren.slice(blockStart));
  });

  docChildren.push(...headerLines.filter(line => line.area === 'footer').map(headerParagraph));

  // Cuối đề thi
  docChildren.push(
    new Paragraph({
      alignment: AlignmentType.CENTER,
      spacing: { before: 400, after: 400 },
      children: [
        new TextRun({
          text: '-------------------------- HẾT --------------------------',
          bold: true,
          font: 'Times New Roman',
          size: 22,
        }),
      ],
    })
  );

  if (['answers', 'solutions', 'matrix'].includes(view)) docChildren.splice(questionBodyStart);

  // NẾU CÓ ĐÁP ÁN & LỜI GIẢI CHI TIẾT
  if (includeSolutions && view !== 'exam' && view !== 'matrix') {
    docChildren.push(
      new Paragraph({
        pageBreakBefore: view === 'all',
        alignment: AlignmentType.CENTER,
        spacing: { before: 200, after: 200 },
        children: [
          new TextRun({
            text: 'ĐÁP ÁN VÀ HƯỚNG DẪN GIẢI CHI TIẾT',
            bold: true,
            size: 26,
            font: 'Times New Roman',
            color: '1E3A8A',
          }),
        ],
      })
    );

    questions.forEach((q, idx) => {
      const answerStart = docChildren.length;
      let answerLabel = '';
      if (q.type === 'multiple_choice') {
        answerLabel = `Đáp án đúng: ${q.correct_answer || 'Chưa đặt đáp án'}`;
      } else if (q.type === 'true_false_group') {
        const tfDetails = q.sub_questions
          ?.map(sq => `${sq.key}) ${sq.isCorrect === undefined ? 'Chưa có đáp án' : sq.isCorrect ? 'Đúng' : 'Sai'}`)
          .join('   ') || '';
        answerLabel = `Đáp án: ${tfDetails || q.correct_answer?.trim() || 'Chưa đặt đáp án'}`;
      } else if (q.type === 'short_answer' || q.type === 'fill_blank') {
        answerLabel = `Đáp số: ${q.correct_answer?.trim() || q.accepted_answers?.filter(value => value.trim()).join(' / ') || 'Chưa đặt đáp án'}`;
      } else if (q.type === 'matching') {
        answerLabel = 'Cặp đúng: ' + (q.matchingPairs?.map(pair => pair.left + ' → ' + pair.right).join('; ') || q.correct_answer || 'Chưa đặt đáp án');
      } else if (q.type === 'ordering') {
        answerLabel = 'Thứ tự đúng: ' + (q.correctOrder?.join(' → ') || q.correct_answer || 'Chưa đặt đáp án');
      } else {
        answerLabel = 'Hướng dẫn chấm / Lời giải:';
      }

      docChildren.push(
        new Paragraph({
          spacing: { before: 160, after: 40 },
          children: [
            new TextRun({
              text: `Câu ${idx + 1}: `,
              bold: true,
              font: 'Times New Roman',
              size: 22,
            }),
            new TextRun({
              text: answerLabel,
              bold: true,
              color: '15803D',
              font: 'Times New Roman',
              size: 22,
            }),
          ],
        })
      );

      // In chi tiết từng ý đúng/sai nếu có explanation
      if (q.type === 'true_false_group' && q.sub_questions) {
        q.sub_questions.forEach(sq => {
          if (sq.explanation) {
            docChildren.push(
              new Paragraph({
                indent: { left: 400 },
                spacing: { after: 30 },
                children: [
                  new TextRun({
                    text: `Ý ${sq.key}) (${sq.isCorrect === undefined ? 'Chưa có đáp án' : sq.isCorrect ? 'Đúng' : 'Sai'}): `,
                    bold: true,
                    font: 'Times New Roman',
                    size: 20,
                  }),
                  ...renderLatexRunsForWord(sq.explanation, { fontSize: 20 }),
                ],
              })
            );
          }
        });
      }

      // In barem chấm điểm nếu có rubric
      if (q.rubric && q.rubric.length > 0) {
        const rubricRows = [
          new TableRow({
            children: [
              new TableCell({
                width: { size: 75, type: WidthType.PERCENTAGE },
                children: [
                  new Paragraph({
                    children: [new TextRun({ text: 'Tiêu chí đánh giá / Yêu cầu cần đạt', bold: true, size: 20, font: 'Times New Roman' })],
                  }),
                ],
              }),
              new TableCell({
                width: { size: 25, type: WidthType.PERCENTAGE },
                children: [
                  new Paragraph({
                    alignment: AlignmentType.CENTER,
                    children: [new TextRun({ text: 'Điểm tối đa', bold: true, size: 20, font: 'Times New Roman' })],
                  }),
                ],
              }),
            ],
          }),
          ...q.rubric.map(r => new TableRow({
            children: [
              new TableCell({
                width: { size: 75, type: WidthType.PERCENTAGE },
                children: [
                  new Paragraph({
                    children: [new TextRun({ text: r.criterion, size: 20, font: 'Times New Roman' })],
                  }),
                ],
              }),
              new TableCell({
                width: { size: 25, type: WidthType.PERCENTAGE },
                children: [
                  new Paragraph({
                    alignment: AlignmentType.CENTER,
                    children: [new TextRun({ text: `${r.maxPoints}đ`, bold: true, size: 20, font: 'Times New Roman' })],
                  }),
                ],
              }),
            ],
          })),
        ];

        docChildren.push(
          new Table({
            width: { size: 90, type: WidthType.PERCENTAGE },
            rows: rubricRows,
          }),
          new Paragraph({ spacing: { after: 120 } })
        );
      }

      if (q.step_by_step_solution && view !== 'answers') {
        docChildren.push(
          new Paragraph({
            indent: { left: 400 },
            spacing: { after: 120 },
            children: [
              ...renderLatexRunsForWord(q.step_by_step_solution, { fontSize: 20 }),
            ],
          })
        );
      }
      parallelAnswers.push(docChildren.slice(answerStart));
    });
  }

  if (view === 'parallel') {
    const label = (text: string) => new Paragraph({ children: [new TextRun({ text, bold: true, font: 'Times New Roman', size: 22 })] });
    const cell = (children: (Paragraph | Table)[]) => new TableCell({ width: { size: 50, type: WidthType.PERCENTAGE }, children: [...children, new Paragraph('')] });
    // Reuse exactly the same question/answer renderers; remove their sequential
    // copies. Shared passages stay full width once, outside the two-column table.
    docChildren.splice(questionBodyStart, docChildren.length - questionBodyStart,
      ...headerBlocks, label('ĐỀ VÀ ĐÁP ÁN SONG SONG'), ...passageBlocks,
      new Table({ width: { size: 100, type: WidthType.PERCENTAGE }, rows: [
        new TableRow({ tableHeader: true, children: [cell([label('Đề bài')]), cell([label('Đáp án / hướng dẫn chấm')])] }),
        ...parallelQuestions.map((blocks, index) => new TableRow({ children: [cell(blocks), cell(parallelAnswers[index] ?? [new Paragraph('Không kèm đáp án trong lần xuất này.')])] })),
      ] }),
      ...headerLines.filter(line => line.area === 'footer').map(headerParagraph));
  }

  // Khởi tạo Document
  const doc = new Document({
    sections: [
      {
        properties: {
          page: {
            margin: {
              top: 1000,
              bottom: 1000,
              left: 1200,
              right: 1200,
            },
          },
        },
        children: docChildren,
      },
    ],
  });

  return await Packer.toBlob(doc);
}

import prisma from '../src/lib/prisma';
import { executeWithKeyRotation, checkUserAiQuota, getRegisteredKeys } from '../src/lib/gemini-keys';
import { Role, QuestionType, Difficulty, Visibility, SourceKind, AiKeyStatus } from '@prisma/client';

async function runPhase2Tests() {
  console.log('🧪 Bắt đầu kiểm thử toàn diện Giai đoạn 2 (DB Questions, Exams, Revisions, Fork, 7 AI Keys, Migration)...');

  // 1. Tạo 2 tài khoản giáo viên để test phân quyền và fork
  const teacher1Email = 'gv1_phase2@examcraft.test';
  const teacher2Email = 'gv2_phase2@examcraft.test';

  await prisma.user.deleteMany({
    where: { email: { in: [teacher1Email, teacher2Email] } },
  });

  const teacher1 = await prisma.user.create({
    data: {
      email: teacher1Email,
      name: 'Thầy Trần Toán',
      passwordHash: 'dummy_hash',
      role: Role.TEACHER,
      aiDailyLimit: 50,
    },
  });

  const teacher2 = await prisma.user.create({
    data: {
      email: teacher2Email,
      name: 'Cô Lê Lí',
      passwordHash: 'dummy_hash',
      role: Role.TEACHER,
      aiDailyLimit: 2, // Đặt thấp để test quota
    },
  });

  console.log('✅ Bước 1: Khởi tạo 2 giáo viên kiểm thử (Thầy Toán & Cô Lí).');

  // 2. Test Tạo câu hỏi và QuestionRevision ban đầu
  const q1 = await prisma.$transaction(async (tx) => {
    const q = await tx.question.create({
      data: {
        ownerId: teacher1.id,
        authorId: teacher1.id,
        subject: 'toan',
        grade: 12,
        type: QuestionType.MULTIPLE_CHOICE,
        difficulty: Difficulty.THONG_HIEU,
        content: 'Cho hàm số $y = f(x)$ có bảng biến thiên...',
        payload: {
          choices: [
            { key: 'A', text: 'Cực đại tại $x = 0$' },
            { key: 'B', text: 'Cực tiểu tại $x = 2$' },
          ],
          correct: 'A',
        },
        solution: 'Dựa vào BBT ta có cực đại tại x = 0',
        visibility: Visibility.SHARED,
        shareable: true,
        version: 1,
      },
    });

    await tx.questionRevision.create({
      data: {
        questionId: q.id,
        version: 1,
        snapshot: JSON.parse(JSON.stringify(q)),
        note: 'Bản khởi tạo v1',
      },
    });

    return q;
  });

  const revCount = await prisma.questionRevision.count({ where: { questionId: q1.id } });
  if (revCount !== 1) {
    throw new Error('❌ Test 2 Thất bại: Không ghi nhận được QuestionRevision v1!');
  }
  console.log('✅ Bước 2: Tạo câu hỏi và lưu QuestionRevision v1 thành công.');

  // 3. Test Cập nhật câu hỏi lên v2 và lưu QuestionRevision v2
  const q1Updated = await prisma.$transaction(async (tx) => {
    const q = await tx.question.update({
      where: { id: q1.id },
      data: {
        content: 'Cho hàm số $y = f(x)$ đã được AI đổi số liệu...',
        version: 2,
      },
    });

    await tx.questionRevision.create({
      data: {
        questionId: q.id,
        version: 2,
        snapshot: JSON.parse(JSON.stringify(q)),
        note: 'AI đổi số liệu câu hỏi',
      },
    });

    return q;
  });

  if (q1Updated.version !== 2) {
    throw new Error('❌ Test 3 Thất bại: Version không tăng lên 2!');
  }
  console.log('✅ Bước 3: Cập nhật câu hỏi và lưu QuestionRevision v2 thành công.');

  // 4. Test Hoàn tác (Rollback) về v1 -> Tạo v3
  const rev1 = await prisma.questionRevision.findUnique({
    where: { questionId_version: { questionId: q1.id, version: 1 } },
  });
  const snapshot1 = rev1!.snapshot as { content: string };

  const q1RolledBack = await prisma.$transaction(async (tx) => {
    const q = await tx.question.update({
      where: { id: q1.id },
      data: {
        content: snapshot1.content,
        version: 3,
      },
    });

    await tx.questionRevision.create({
      data: {
        questionId: q.id,
        version: 3,
        snapshot: JSON.parse(JSON.stringify(q)),
        note: 'Hoàn tác về v1',
      },
    });

    return q;
  });

  if (q1RolledBack.content !== q1.content || q1RolledBack.version !== 3) {
    throw new Error('❌ Test 4 Thất bại: Hoàn tác về v1 không khôi phục đúng nội dung!');
  }
  console.log('✅ Bước 4: Hoàn tác (Rollback) về phiên bản cũ thành công với đầy đủ lịch sử revision.');

  // 5. Test Nhân bản (Fork) câu hỏi dùng chung giữa các giáo viên
  const forkedQ = await prisma.$transaction(async (tx) => {
    const q = await tx.question.create({
      data: {
        ownerId: teacher2.id, // Cô Lí nhận bản sao
        authorId: q1.authorId, // Tác giả gốc vẫn là Thầy Toán
        originId: q1.id, // Trỏ về câu gốc
        subject: q1.subject,
        grade: q1.grade,
        type: q1.type,
        difficulty: q1.difficulty,
        content: q1.content,
        payload: q1.payload as object,
        solution: q1.solution,
        visibility: Visibility.PRIVATE,
        sourceKind: SourceKind.FORKED,
        version: 1,
      },
    });

    await tx.questionRevision.create({
      data: {
        questionId: q.id,
        version: 1,
        snapshot: JSON.parse(JSON.stringify(q)),
        note: `Nhân bản từ câu hỏi gốc của Thầy Trần Toán`,
      },
    });

    return q;
  });

  if (forkedQ.ownerId !== teacher2.id || forkedQ.authorId !== teacher1.id || forkedQ.originId !== q1.id) {
    throw new Error('❌ Test 5 Thất bại: Thông tin nguồn gốc khi Fork câu hỏi không chính xác!');
  }
  console.log('✅ Bước 5: Fork câu hỏi từ Ngân hàng dùng chung bảo toàn 100% tác giả gốc (authorId) và originId.');

  // 6. Test Tạo đề thi và liên kết ExamQuestion
  const exam = await prisma.$transaction(async (tx) => {
    const ex = await tx.exam.create({
      data: {
