  // Đúng 1 ý: 0.1đ | Đúng 2 ý: 0.25đ | Đúng 3 ý: 0.5đ | Đúng 4 ý: 1.0đ
  function calculateTrueFalseScore(correctCount: number): number {
    switch (correctCount) {
      case 1: return 0.1;
      case 2: return 0.25;
      case 3: return 0.5;
      case 4: return 1.0;
      default: return 0.0;
    }
  }

